COLLDATA("jamulfawaid","ur",[[1512,"زید بن وہب سے روایت ہے کہ سیدنا حذیفہ رضی اللہ عنہ نے ایک آدمی کو نماز پڑھتے دیکھا کہ اس نے نماز میں بہت کمی کی۔ پس سیدنا حذیفہ رضی اللہ عنہ نے کہا: تو کتنے عرصے سے ایسی نماز پڑھ رہا ہے؟ اس نے کہا: چالیس سال سے۔ انہوں نے کہا: تو نے چالیس سال سے نماز نہیں پڑھی اگر تو اسی طرح نماز پڑھتے فوت ہوا تو محمد صلی اللہ علیہ وسلم کی فطرت کے خلاف فوت ہوگا۔‘‘","",{"k":"نسائی (1312)، صحیح الاسناد: 1244، بخاری (389)، احمد (22851)","e":"یہ مرفوع کے حکم میں ہے، یہ حدیث رکوع اور سجدے میں اطمینان کے فرض ہونے کی دلیل ہے اور اطمینان میں خلل آجائے تو نماز باطل ہو جاتی ہے۔ ۲۔ جب نماز کے ارکان میں خلل واقع کرنے سے فطرت اسلامی چھوٹ جاتی ہے، تو نماز کا تارک کتنا بڑا کفر کرتا ہے۔ ۳۔ سیدنا حذیفہ رضی اللہ عنہ نے ارکان میں خلل واقع کرنے والے کو اس لیے ڈانٹا تھا تاکہ مستقبل میں اس کی نماز کی اصلاح ہو جائے۔"}],[1513,"سیدنا ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب رکوع کرتے تو پشت کو برابر رکھتے تھے اگر بالفرض آپ صلی اللہ علیہ وسلم کی پشت پر پانی ڈالا جاتا تو پانی ٹھہر جاتا۔ (الکبیر اور الاوسط)","",{"k":"طبرانی کبیر: 12781، ابویعلی موصلی ورجالہ موثقون، ہیثمی: 2737۔","e":"اس حدیث میں رکوع کے اعتدال کی کیفیت بیان ہوئی ہے کہ اوپر پانی کا برتن رکھ دیں تو نبی اکرم صلی اللہ علیہ وسلم کی کمر مبارک سے اچھلتا نہ تھا۔ اتنی برابر ہوتی تھی۔"}],[1514,"سیدنا ابن عباس رضی اللہ عنہما سے مرفوع حدیث میں منقول ہے: ’’جو شخص ناک کو پیشانی کے ساتھ زمین پر نہیں رکھتا جب وہ سجدہ کرتا ہے تو اس کی نماز کفایت نہیں کرتی۔‘‘ (الکبیر اور الاوسط)","",{"k":"طبرانی کبیر: 11917، طبرانی اوسط ورجالہ موثقون، ہیثمی: 2762۔","e":"اس میں دلیل ہے کہ پیشانی کے ساتھ سجدے میں ناک بھی زمین پر لگائیں وگرنہ نماز قبول نہ ہوگی۔"}],[1515,"طاؤس سے روایت ہے، کہتے ہیں کہ ہم نے ابن عباس رضی اللہ عنہما سے دو پاؤں پر اقعاء کرنے کے بارے میں سوال کیا تو انہوں نے کہا: یہ سنت میں سے ہے۔ ہم نے کہا: کیا تو اس کو آدمی کی زیادتی نہیں سمجھتا؟ انہوں نے کہا: یہ تمہارے نبی صلی اللہ علیہ وسلم کی سنت ہے۔","",{"k":"مسلم (536)، ترمذی (283)، ابوداؤد (845)، احمد (2850)۔","e":"اس حدیث میں اقعاء کی اجازت بیان ہوئی ہے۔ یہ ایک انداز نشست ہے، جو دو سجدوں کے درمیان اختیار کیا جاتا ہے، اس کی دو قسمیں ہیں: (۱) دونوں پنڈلیاں کھڑی رکھیں اور سرین زمین پر ٹکا دیں اور ہاتھ زمین پر رکھیں، یہ وہ صورت ہے جس کی ممانعت ہے، اسے ہی کتے سے بیٹھنے کے ساتھ تشبیہ دی گئی ہے۔ (۲) اقعاء کی صورت یہ ہے کہ دو سجدوں کے درمیان پاؤں کھڑے کریں اور ان پر بیٹھ جائیں، یہ جائز ہے۔ اس تعریف سے دونوں احادیث میں مطابقت ہوئی کہ ایک میں اس کی ممانعت آئی ہے، دوسری حدیث میں اسے سنت قرار دیا گیا ہے۔ تو منع وہ ہے جس میں کتے کی مشابہت ہے جو ہم نے اوپر نمبر ۱ میں بیان کی ہے اور جائز وہ ہے جو ہم نے نمبر ۲ میں بیان کی ہے۔ یہ جائز ہے، بہر صورت بہتر اور افضل یہی ہے کہ دو سجدوں کے درمیان بایاں پاؤں زمین پر بچھایا جائے اور اس پر سرین رکھیں اور دایاں پاؤں کھڑا کیا جائے۔ باقی جائز دونوں انداز نشست ہیں۔ (مرعاۃ: ۲/۴۶۳، عون المعبود: ۱/۳۱۴، تحفۃ الاحوذی: ۱/۲۳۵)"}],[1516,"سیدنا عبداللہ ابن مسعود رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم جب پہلی دو رکعات کے بعد بیٹھتے تو گویا آپ صلی اللہ علیہ وسلم پتھر پر بیٹھے ہوں، یہاں تک کہ جلدی کھڑے ہو جاتے۔","",{"k":"احمد (4144)، ترمذی (366)، نسائی (1176)، ابوداؤد (995)۔","e":"اس میں بیان ہوا ہے کہ تین رکعات والی نماز ہو یا چار رکعات والی ہو جس میں دو تشہد آتے ہیں، پہلے تشہد میں تخفیف کی جائے کیونکہ یہ کہنا کہ گویا گرم پتھر پر بیٹھے تھے، یہ جلدی اٹھنے پر دلالت کرتا ہے یعنی صرف عبدہ ورسولہ تک پڑھ کر کھڑے ہو جائیں، درود اور دعائیں نہ پڑھیں۔ اگر کوئی اس سے آگے درود پڑھ لیتا ہے تو حرج نہیں مگر جو یہ کہتے ہیں کہ تشہد سے آگے پڑھنے سے سجدہ سہو پڑ جاتا ہے تو یہ بے دلیل بات ہے۔ اس حدیث میں جس میں گرم پتھر پر بیٹھنے کا کہا گیا ہے انقطاع ہے کہ ابوعبیدہ نے اپنے باپ سے حدیث نہیں سنی۔ مگر ترمذی نے شواہد کی بنا پر اسے حسن کہا ہے۔ یہ بات مضبوط ہے کیونکہ سیدنا ابوبکر رضی اللہ عنہ بھی اس تشہد میں مختصر ہی بیٹھا کرتے تھے۔ (ابن ابی شیبہ، اسنادہ صحیح)\nسیدنا ابن مسعود رضی اللہ عنہ نے پہلے تشہد میں عبدہ ورسولہ تک پڑھا تو اوپر کھڑے ہو گئے، حالانکہ انہوں نے کہا تھا کہ میں رسول اکرم صلی اللہ علیہ وسلم والی نماز بتاتا ہوں۔ (مسند احمد، صحیح ابن خزیمہ) یہ ساری روایات پہلے تشہد میں جلدی اٹھنے کی تائید کرتی ہیں۔ (مرعاۃ: ۲/۴۸۲)"}],[1517,"عبداللہ بن عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں میں ابن عمر رضی اللہ عنہما کو دیکھا کرتا تھا کہ جب وہ نماز میں بیٹھتے تو چار زانو ہو کر بیٹھتے تھے۔ تو میں نے بھی ایسا کیا تو ابن عمر رضی اللہ عنہما نے مجھے منع کر دیا اور کہا نماز میں سنت طریقہ یہ ہے کہ دائیں پاؤں کو کھڑا کیا جائے اور بائیں پاؤں کو بچھا کر بیٹھے۔ میں نے کہا: تم خود تو چار زانو ہو کر بیٹھتے ہو؟ انہوں نے کہا: میرے پاؤں مجھے اٹھانے کے متحمل نہیں ہیں۔","",{"k":"بخاری (827)، ترمذی (3867)، نسائی (1157)، ابوداؤد (959)، مؤطا (202)۔","e":"اس حدیث میں تشہد میں بیٹھنے کا طریقہ بتایا گیا ہے کہ بایاں پاؤں موڑ لیں اور دایاں پاؤں کھڑا رکھیں۔ یہ یاد رہے یہ پہلے تشہد میں بیٹھنے کا طریقہ ہے۔ ۲۔ یہ ثابت ہوا کہ اگر ضعف یا بیماری ہو تو چار زانو (چوکڑی مار کر) بیٹھ کر نماز جائز ہے مگر صحت مند کے لیے اس کی قطعاً اجازت نہیں۔"}],[1518,"علی بن عبدالرحمن المعاوی سے روایت ہے کہ مجھے ابن عمر رضی اللہ عنہما نے نماز میں کنکروں سے کھیلتے دیکھا۔ جب انہوں نے سلام پھیرا تو مجھے منع کیا اور کہا: اس طرح کر جیسے رسول اللہ صلی اللہ علیہ وسلم کیا کرتے تھے۔ میں نے کہا: آپ صلی اللہ علیہ وسلم کیسے کرتے تھے؟ تو انہوں نے کہا: جب آپ صلی اللہ علیہ وسلم نماز میں بیٹھتے تو اپنا دایاں ہاتھ دائیں ران پر رکھتے اور تمام انگلیاں بند کر دیتے اور اس انگلی کے ساتھ اشارہ کرتے جو انگوٹھے کے ساتھ ہے اور بائیں ہاتھ کو بائیں ران پر رکھتے تھے۔","",{"k":"مسلم (580)، ترمذی (294)، نسائی (1269)، ابوداؤد (987)، ابن ماجہ (913)، احمد (6312)، مؤطا (199)، دارمی (1339)۔"}],[1519,"اور ایک روایت میں ہے: اپنے بائیں ہاتھ کو بائیں گھٹنے پر رکھتے اور اپنے دائیں ہاتھ کو دائیں گھٹنے پر رکھتے، اور ترپن کا عدد بناتے اور انگشت شہادت سے اشارہ کرتے تھے۔","",{"k":"مسلم (580)، ترمذی (294)، نسائی (1269)، ابوداؤد (987)، ابن ماجہ (913)، احمد (6312)، مؤطا (199)، دارمی (1339)۔"}],[1520,"سیدنا عبداللہ بن زبیر رضی اللہ عنہما سے روایت اس کی مثل ہے اور اس میں ہے کہ جب دعا کرتے تو اپنی انگلی سے اشارہ کرتے اور انگلی کو حرکت نہ دیتے تھے۔","",{"k":"نسائی (1270)، شاذ البانی: 67، ولا یحرکھا کے الفاظ شاذ ہیں۔ دوسری حدیث مسلم کے 579، ابوداؤد (989)، احمد (1522)۔"}],[1521,"اور ترمذی میں مثل اس کے ہے: آپ صلی اللہ علیہ وسلم دیگر انگلیاں بند کرتے اور شہادت کی انگلی کو کشادہ کرتے اور دعا کرتے اور کہتے: ’’اے دلوں کو پھیرنے والے! میرے دل کو اپنے دین پر ثابت کر دے۔‘‘","",{"k":"ترمذی (3587)، منکر بھذا السیاق، البانی: 723۔","e":"اس میں التحیات میں ہاتھ رکھنے کا یہ طریقہ بیان ہوا ہے کہ بایاں ہاتھ بائیں گھٹنے پر اور دایاں ہاتھ دائیں گھٹنے پر رکھا جائے۔ ۲۔ دائیں ہاتھ پر ترپن کی گرہ باندھی جائے اور بایاں ہاتھ کھول کر بائیں گھٹنے پر رکھا جائے۔ ۳۔ ترپن کی گرہ یہ ہے کہ سب سے چھوٹی انگلی اور اس کے ساتھ والی انگلی اور درمیان والی انگلی تینوں کو ہتھیلی کے ساتھ اکٹھا کریں اور سبابہ انگلی کھلی رکھی جائے، اسے انگوٹھے کی جڑ میں ملا دیا جائے تو یہ ترپن کی گنتی کی کیفیت بن جاتی ہے۔ بظاہر تو یہی معلوم ہوتا ہے کہ تشہد میں بیٹھتے ہی آپ صلی اللہ علیہ وسلم انگلی اٹھا لیتے تھے، اور اشارہ لا الہ الا اللہ پر کرتے تھے، اشارہ ایک دفعہ ہی کافی ہے بار بار کرنے کی ضرورت نہیں۔ ایک دفعہ ہی اشارہ کرنے سے حدیث پر عمل ہو جاتا ہے۔\nحرکت واشارہ نہ کرنے والی بات صحیح نہیں۔ انگلی سے اشارہ کرنا مسنون عمل ہے۔ ۴۔ تشہد میں ایک حالت تو یہ بیان ہو چکی ہے جو کہ ترپن والی ہے۔ تشہد میں بیٹھنے کی دوسری کیفیت یہ ہے کہ ہتھیلی پر تمام انگلیاں ملائی جائیں اور سبابہ انگلی سے اشارہ کیا جائے۔ (۳) یہ طریقہ ہے کہ سب سے چھوٹی انگلی اور اس کے ساتھ والی انگلی ہتھیلی کے ساتھ ملائی جائیں اور سبابہ کھلی رکھی جائے اس سے اشارہ کیا جائے اور درمیان والی انگلی اور انگوٹھے کا حلقہ بنالیا جائے۔ ایک یہ طریقہ ہے کہ دایاں ہاتھ دائیں ران پر رکھا جائے اور سبابہ کے ساتھ اشارہ کیا جائے۔ (مرعاۃ: ۲/۴۶۷) ان چاروں طریقوں پر آپ صلی اللہ علیہ وسلم کا تشہد میں بیٹھنا معمول تھا، مختلف اوقات میں مختلف انداز پر آپ صلی اللہ علیہ وسلم کا تشہد میں جلوہ افروز رہے ہیں، یہ سب جائز ہیں۔"}],[1522,"ابو یعفور نے کہا: میں نے مصعب بن سعد سے سنا: اس نے کہا: میں نے اپنے باپ کے پہلو میں نماز پڑھی اور میں نے اپنی ہتھیلیاں ملائیں اور ان دونوں کو اپنی ران کے درمیان رکھا تو میرے باپ نے اس سے مجھے منع کیا اور کہا: ہم پہلے اس طرح رکھتے تھے پھر ہمیں اس سے منع کیا گیا اور ہمیں حکم دیا گیا کہ ہم اپنے ہاتھ اپنے گھٹنوں پر رکھا کریں۔‘‘ (الشیخین، ابوداؤد اور نسائی) اصل میں اس کو اسی طرح جلوس کے باب میں بیان کیا ہے باوجود اس کے کہ دیگر محدثین نے اس کو باب رکوع میں ذکر کیا ہے۔","",{"k":"بخاری (790)، مسلم (535)، ترمذی (259)، نسائی (1033)، ابوداؤد (867)، ابن ماجہ (873)، احمد (1574)، دارمی (1303)۔"}],[1523,"مصعب بن سعد بن ابی وقاص کہتے ہیں کہ میں نے اپنے باپ کے پہلو میں نماز پڑھی اور جب میں نے رکوع کیا تو میں نے اپنی ایک ہاتھ کی انگلیاں دوسرے ہاتھ کی انگلیوں میں ڈال کر تشبیک کی اور دونوں ہاتھوں کو گھٹنوں کے درمیان رکھ دیا تو انہوں نے میرے ہاتھ پر مارا۔","",{"k":"بخاری (790)، مسلم (535)، ترمذی (259)، نسائی (1033)، ابوداؤد (867)، ابن ماجہ (873)، احمد (1574)، دارمی (1303)۔"}],[1524,"دوسری روایت ہے: میں نے رکوع کیا اور اپنے ہاتھ اس طرح کیے یعنی ہر دو ہاتھ ملائے اور ان دونوں کو اپنی دو رانوں کے درمیان رکھا۔‘‘ (مثل روایت سابق ہے)","",{"e":"..... اوپر وضاحت گزر چکی ہے کہ گھٹنوں کے درمیان ہاتھ رکھنے منسوخ ہو چکے ہیں، اب مسنون طریقہ گھٹنوں کے اوپر ہاتھ رکھنا ہے۔"}],[1525,"سیدنا ابن مسعود رضی اللہ عنہ سے روایت ہے کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے تشہد تعلیم فرمایا جبکہ میرا ہاتھ آپ صلی اللہ علیہ وسلم کے ہاتھوں کے درمیان تھا۔ جیسے آپ صلی اللہ علیہ وسلم مجھے قرآن کی سورت کی تعلیم دیتے تھے۔ تمام عبادات اللہ کی ہیں، نمازیں بھی اور صدقات بھی سب اللہ ہی کے لیے ہیں۔ اے نبی کریم صلی اللہ علیہ وسلم آپ پر سلامتی ہے اور اللہ کی رحمت اور اس کی برکات ہیں۔ سلامتی ہو ہم پر اور اللہ کے تمام نیکو کار بندوں پر۔ میں گواہی دیتا ہوں کہ کوئی عبادت کے لائق نہیں اللہ کے سوا اور میں گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم اللہ کے بندے اور اس کے رسول ہیں۔‘‘","",{"k":"مسلم (535)۔ نسائی (1031)۔ ابوداؤد (868)۔ ابن ماجہ (1255)۔ احمد (4373)۔"}],[1526,"اور ابو داؤد کی ایک روایت میں ہے: جب تو نے یہ کلمات کہے تو نے اپنی نماز مکمل کر لی پس اگر تو کھڑا ہونا چاہے تو کھڑا ہو جا اور اگر تو بیٹھنا چاہے تو بیٹھ جا۔‘‘","",{"k":"بخاری (6265)۔ مسلم (402)۔ ترمذی (1105)۔ نسائی (1198)۔ ابوداؤد (968)۔ ابن ماجہ (899)۔ احمد (4408)۔ دارمی (1341)۔ شاذ، البانی: 205۔"}],[1527,"اور دوسری روایت میں ہے: جب ہم نبی کریم صلی اللہ علیہ وسلم کے ساتھ نماز میں بیٹھتے تو ہم کہتے تھے اللہ پر اس کے بندوں سے پہلے سلام ہو اور سلام ہو فلاں پر اور فلاں پر۔ پس رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: یہ نہ کہو سلام ہو اللہ پر۔ بے شک اللہ تعالیٰ ہی سلامتی عطا کرنے والا ہے۔ البتہ جب تم یہ کلمات کہو گے تو اللہ کے تمام بندوں کو وہ پہنچے گا خواہ آسمان میں ہوں یا وہ زمین کے درمیان رہتے ہوں۔ میں گواہی دیتا ہوں کہ نہیں کوئی عبادت کے قابل اللہ کے سوا اور میں گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم اللہ کے بندے اور اس کے رسول ہیں۔ اس کے بعد تم میں سے جس کو جو دعا مطلوب ہو وہ دعا کرے۔‘‘","",{"k":"ابوداؤد (968)۔"}],[1528,"’’اور ایک روایت میں ان سے اس کے مثل منقول ہے۔ اور کہا آپ صلی اللہ علیہ وسلم ہمیں ان کلمات کی اس طرح تعلیم دیتے جیسے آپ صلی اللہ علیہ وسلم ہمیں تشہد کی تعلیم دیتے تھے: اے اللہ! ہمارے قلوب میں اُلفت اور محبت ڈال اور ہمارے درمیان اصلاح کر اور ہمیں سلامتی کے راستوں پر چلا اور ہمیں ظلمات اور تاریکی سے روشنی کی طرف نجات دے دے اور ہمیں فحش اور بے حیائی کے امور سے دور رکھ جو ظاہر ہیں اور جو چھپے ہیں اور برکت ڈال ہمارے کانوں، ہماری آنکھوں، ہمارے دلوں، ہماری بیویوں اور ہماری اولاد میں اور ہماری توبہ قبول کر، یقینا تو ہی توبہ قبول کرنے والا مہربان ہے اور ہمیں اپنی نعمتوں کا شکر کرنے والا بنا دے۔ ہم تیری نعمتوں پر تیری ثنا بیان کرنے اور ان کو قبول کرنے والے بن جائیں اور تو اپنی نعمتیں ہم پر مکمل کر دے۔ یہ کلمات مکمل ہوتے۔‘‘","",{"k":"ابوداؤد (968)۔"}],[1529,"قاسم بن مخیمرہ کہتے ہیں کہ علقمہ نے میرا ہاتھ پکڑا اور بیان کیا کہ عبداللہ بن مسعود رضی اللہ عنہ نے اس کا ہاتھ پکڑا اور کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کا ہاتھ پکڑ کر انہیں تشہد سکھایا، پھر اعمش کی حدیث کی طرح دعا ذکر کی۔ جب تم یہ کہہ لو تو تمہاری نماز پوری ہوگئی اگر تم کھڑے ہونے چاہو تو کھڑے ہو جاؤ اور اگر تم بیٹھنا چاہو تو بیٹھے رہو۔","",{"k":"ابوداؤد (968)۔ صحیح، البانی: 854۔ بخاری (831)۔ مسلم (402)۔ ترمذی (289)۔ نسائی (1298)۔ ابن ماجہ (899)۔ احمد (4408)۔ دارمی (1341)۔"}],[1530,"’’اور نسائی کی روایت میں ہے: ہم کہا کرتے تھے : سلام ہو اللہ پر، سلام ہو جبرئیل اور میکائیل پر۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم ایسا نہ کہا کرو.... تا آخر حدیث۔‘‘","",{"k":"نسائی (1168)۔ شاذ البانی: 53 بزیادۃ وحدہ لا شریک لہ، بخاری (7381)۔ مسلم (402)۔ ترمذی (289)۔ ابوداؤد (968)۔ ابن ماجہ (899)۔ احمد (4408)۔ دارمی (1341)۔"}],[1531,"سیدنا ابن عباس رضی اللہ عنہ روایت کرتے ہیں: ہمیں رسول اللہ صلی اللہ علیہ وسلم تشہد تعلیم کرتے جیسے ہمیں قرآن کی سورت کی تعلیم دیتے تھے۔ پس آپ صلی اللہ علیہ وسلم فرماتے: تمام بابرکت عبادات، نمازیں اور صدقات اللہ ہی کے لیے ہیں۔ سلامتی ہے تیرے اوپر تا آخر۔‘‘","",{"k":"مسلم (403)۔ ترمذی (290)۔ نسائی (1174)۔ ابوداؤد (974)۔ ابن ماجہ (900)۔ احمد (2887)۔"}],[1532,"اور ایک روایت میں الف اور لام کے بغیر ہے: سَلَامٌ عَلَيْكَ اور سَلَامٌ عَلَيْنَا۔............","",{"k":"نسائی (1064)۔ صحیح، البانی: 1019۔ مسلم (404)۔ ابوداؤد (972)۔ ابن ماجہ (901)۔ احمد (19166)۔ دارمی (1312)۔"}],[1533,"بزار اور الاوسط نے یہ زیادہ کیا ہے: نبی کریم صلی اللہ علیہ وسلم ہمیں تشہد کی تعلیم دیتے تھے اور فرماتے تھے: ’’اس کو سیکھو! تشہد کے بغیر نماز نہیں ہے۔‘‘","",{"k":"طبرانی اوسط، وفیہ صعدی بن سنان ضعفہ ابن معین، ورواہ البزار برجال موثقون وفی بعضہم خلاف لا یضر ان شاء اللہ۔","e":"..... تشہد کو قرآن پاک کی سورت کی مثل سکھانے سے اس کی اہمیت اجاگر ہوتی ہے اور پتہ چلتا ہے کہ تشہد فرض ہے۔ التحیات سے مراد وہ عبادات ہیں جو قولی ہیں والصلوات سے مراد بدنی عبادات ہیں والطیبات سے مراد مالی عبادات ہیں یعنی یہ تمام عبادات اللہ کے لیے خاص ہیں۔ ۳۔ السلام علیک سے قبر پرستی کے مرتکب یہ استدلال کرتے ہیں کہ رسول اکرم صلی اللہ علیہ وسلم کو نماز کے علاوہ بھی پکارا جا سکتا ہے۔ مگر یہ استدلال درست نہیں۔ (۱) اس وجہ سے کہ بعض صحابہ کرام رضی اللہ عنہم نے اس خطاب کے صیغہ کو تبدیل کر دیا تھا تا کہ یہ شبہ باقی نہ رہے۔ وہ کہتے تھے: السلام علی النبی نبی پر سلامتی ہو۔ (بخاری، کتاب الاستیذان) (۲) یہ مشہور ہے کہ معراج کی رات نبی اکرم صلی اللہ علیہ وسلم نے اللہ تعالیٰ کی بے شمار حمد وثنا کی تھی، اس کے جواب میں اللہ تعالیٰ نے آپ کو مخاطب کیا اور اسے آپ نماز میں دہراتے تھے۔ (مسک الختام) (۳) یہ ضروری نہیں جسے مخاطب کیا جاتا ہے وہ سامنے حاضر ہی ہو۔ جب نبی اکرم صلی اللہ علیہ وسلم خود پڑھتے تھے تو سامنے کون ہوتا تھا۔ ثابت ہوا کہ یہ ایک دعا ہے جو آپ صلی اللہ علیہ وسلم خود بھی دہراتے تھے، ہمیں بھی دہرانے کا حکم ہے۔ ۴۔ یہ یاد رہے کہ ان میں صحیح ترین اس تشہد کے الفاظ ہیں جو سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے بیان کیے ہیں اور اس کے بعد سیدنا عبداللہ بن عباس رضی اللہ عنہما والے ہیں۔ اس کی ایک وجہ یہ ہے کہ ان کے تشہد کے راوی کسی لفظ میں مختلف نہیں ہوئے جبکہ دوسرے تشہد کو یہ شرف حاصل نہیں ان میں اختلاف ہے۔ دوسری وجہ یہ ہے انہوں نے خود نبی اکرم صلی اللہ علیہ وسلم کے زبان مبارک سے یہ تشہد سنا ہے اور آپ صلی اللہ علیہ وسلم نے ان کا ہاتھ اپنے ہاتھوں میں دے رکھا تھا، جب اس کی آپ تعلیم دے رہے تھے۔ جبکہ دوسرے تشہدوں کو یہ مقام نہیں ملا۔"}],[1534,"الکبیر میں تشہد کے بعد کی یہ دعا منقول ہے: ’’تو پاک ہے، تیرے سوا کوئی معبود نہیں ہے، میرے گناہ بخش دے، میرے عمل کی اصلاح کر دے، تو ہی گناہ بخشتا ہے جس کو چاہے اور تو بخشنے والا مہربان ہے۔ اے بخشنے والے مجھے بخش دے، اے توبہ قبول کرنے والے! میری طرف رجوع کر، اے رحم کرنے والے! میرے اوپر رحم کرے دے، اے عافیت دینے والے! مجھے عافیت دے دے، اے شفقت کرنے والے میرے اوپر شفقت فرما۔ اے میرے رب! مجھے توفیق دے تاکہ میں تیری ان نعمتوں کا شکر کروں جو تو نے میرے اوپر انعام کی ہیں اور مجھے بہتر طور پر اپنی عبادت کی توفیق عطا کر۔ یا اللہ! میں تیری ہر بھلائی کا سوال کرتا ہوں اور میں ہر شر سے تیری پناہ طلب کرتا ہوں۔ اے میرے رب! میرے لیے ابتداء کر اور کھول بھلائی کے ساتھ اور بھلائی پر اختتام کر اور مجھے اپنی ملاقات کا شوق عطا کر جو بغیر نقصان اور ضرر کے ہو اور گمراہ کن فتنے سے نہ ہو۔ اور مجھے تمام بدیوں سے بچا اور آج جس کو تو نے بدی سے بچا لیا اس پر تو نے رحم کر دیا اور یہ بہت بڑی کامیابی ہے۔‘‘","",{"k":"طبرانی کبیر، وابو عبیدہ لم یسمع من ابیہ، ہیثمی: 2862۔"}],[1535,"سیدنا عبداللہ بن مسعود رضی اللہ عنہ کی مرفوع روایت میں ہے: اے اللہ! ہم تجھ سے ہر بھلائی کا سوال کرتے ہیں، دنیا کی بھلائی اور آخرت کی بھلائی کا جو ہم جانتے ہیں اور جو ہم نہیں جانتے ہیں۔ تیری پناہ طلب کرتا ہوں ہر شر سے خواہ وہ دنیا کا شر ہو یا آخرت کا شر ہو، ہم جس کو جانتے ہیں یا وہ جس کو ہم نہیں جانتے۔ اے اللہ! ہم تجھ سے اس چیز کا سوال کرتے ہیں جس کا تجھ سے تیرے نیک بندوں نے سوال کیا ہے اور ہم تیری پناہ مانگتے ہیں ہر اس چیز سے جس کے شر سے تیرے نیک بندوں نے پناہ طلب کی ہے۔ اے اللہ! ہمیں دنیا میں بھی بھلائی عطا کر اور آخرت میں بھی بھلائی عنایت فرما اور ہمیں آگ کے عذاب سے بچا۔ اے ہمارے رب! ہم ایمان لائے ہیں۔ پس ہمیں بخش اور بدیاں ہم سے دور کر دے اور ہمیں نیک لوگوں کے ساتھ موت دے۔ اے ہمارے رب! ہمیں وہ عطا کر جس کا تو نے اپنے رسولوں کی زبان پر ہم سے وعدہ کیا ہے اور ہمیں قیامت کے دن رسوا نہ کر یقیناً تو وعدے کے خلاف نہیں کرتا۔‘‘","",{"k":"طبرانی کبیر، وفی الاوسط، ہیثمی: 2864۔"}],[1536,"ضعیف سند کے ساتھ دوسری روایت ہے: ابن مسعود رضی اللہ عنہ نے کہا کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے تعلیم دی: ہر قسم کی عبادت اللہ کے لیے ہے۔۔۔۔۔۔تارسولہ اور اس میں یہ الفاظ زیادہ ہیں: اے اللہ! رحمت و صلوت نازل فرما محمد صلی اللہ علیہ وسلم اور ان کے اہل بیت پر جیسے تو نے صلوۃ نازل کیں ابراہیم علیہ السلام پر، بے شک تو صفتوں والا عظمت والا ہے۔ اے اللہ! ان کے ساتھ ہم پر بھی صلوۃ نازل فرما۔ اے اللہ! برکات نازل فرما محمد صلی اللہ علیہ وسلم اور ان کے اہل خانہ پر جیسے تو نے برکات نازل کیں ابراہیم علیہ السلام پر بے شک تو صفتوں والا عزت والا ہے۔ اے اللہ! ان کے ساتھ ہم پر بھی برکات نازل کر۔ اللہ کی صلوت اور اہل ایمان کی دعائیں اور درود ہوں محمد النبی الامی صلی اللہ علیہ وسلم پر، سلامتی ہو ان پر اور اللہ کی رحمت اور اس کی برکات نازل ہوں۔‘‘","",{"k":"طبرانی کبیر: 9937، وفیہ عبدالوہاب بن مجاہد وہو ضعیف، ہیثمی: 2872."}],[1537,"’’نسائی میں ابو موسیٰ رضی اللہ عنہ سے مرفوع حدیث منقول ہے: جب قعدہ میں ہو تو تم میں سے ہر ایک کا یہ قول ہونا چاہیے: تمام عبادات اللہ کے لیے ہیں پاکیزہ صدقات اور نمازیں، اے نبی! تیرے اوپر سلامتی ہے اور اللہ کی رحمت ہے۔ اور اس کی برکات ہیں۔ سلامتی ہو ہم پر اور اللہ کے تمام نیک بندوں پر۔ میں گواہی دیتا ہوں کہ نہیں کوئی معبود مگر اللہ۔ وہ ایک ہے، اس کا کوئی شریک نہیں ہے اور یہ کہ محمد صلی اللہ علیہ وسلم اللہ کے بندے اور اس کے رسول ہیں۔‘‘","",{"k":"نسائی (1172)، صحیح، البانی: 1122، مسلم (404)، ابوداؤد (972)، ابن ماجہ (901)، احمد (9166)، دارمی (1312)."}],[1538,"سیدنا جابر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہمیں تشہد کی تعلیم دیتے تھے جیسے بتاکید ہمیں قرآن کی سورت تعلیم فرماتے تھے۔ اللہ کے نام کے ساتھ اللہ کے ساتھ، تمام عبادات اللہ ہی کے لیے ہیں، ابن مسعود رضی اللہ عنہ سے منقول تشہد کے آخر تک۔ اور اس کے آخر میں ان کلمات کو زیادہ کیا ہے: ’’میں اللہ سے جنت کا سوال کرتا ہوں اور اللہ تعالیٰ کی پناہ طلب کرتا ہوں جہنم سے۔‘‘","",{"k":"نسائی (1175)، ضعیف، البانی: 54، ابن ماجہ (902)."}],[1539,"سیدنا ابن عمر رضی اللہ عنہما سے روایت ہے کہ وہ یہ تشہد پڑھتے تھے: اللہ کے نام سے، سب عبادات اللہ کے لیے ہیں، تمام نمازیں اللہ کے لیے ہیں، پاکیزہ صدقات اللہ کے لیے ہیں، نبی کریم صلی اللہ علیہ وسلم پر سلامتی اور اللہ کی رحمت اور اس کی برکات نازل ہوں، سلامتی ہو ہم پر اور اللہ کے تمام نیک بندوں پر، میں نے گواہی دی ہے کہ نہیں کوئی عبادت کے لائق مگر اللہ اور میں نے گواہی دی ہے کہ محمد صلی اللہ علیہ وسلم اللہ کے رسول ہیں۔ یہ پہلی دو رکعات کے بعد کے قعدے میں کہے اور جب تشہد پڑھ چکے تو جو چاہے دعا کرے اور جب نماز کے آخر میں بیٹھے تو اس میں تشہد پڑھے البتہ یہ ضروری ہے کہ پہلے تشہد پڑھے اور اس کے بعد دعا مانگے اور جو چاہے دعا کرے اور جب سلام پھیرنا چاہے تو یہ کہے: سلام ہو نبی کریم پر اور اللہ کی رحمت اور اس کی برکات ہوں اور ہم پر سلامتی ہو اور اللہ کے تمام بندوں پر۔ پھر دائیں طرف کہے: سلامتی ہو تم پر اور پھر امام کے سلام کا جواب دے اور اگر اس کے بائیں طرف سے کسی شخص نے سلام پھیرا ہو تو اس کو سلام کا بھی جواب دے۔","",{"k":"مؤطا (205) -"}],[1540,"رزین نے یہ زائد الفاظ نقل کیے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے ان کو یہ حکم دیا ہے۔","",{"k":"مؤطا (205) -"}],[1541,"سیدہ عائشہ رضی اللہ عنہا تشہد میں کہا کرتی تھیں: ’’عبادات، طیبات اور صلوت پاکیزہ اللہ ہی کے لیے ہیں، میں گواہی دیتی ہوں کہ نہیں کوئی معبود اللہ کے علاوہ، وہ ایک ہے اور اس کا کوئی شریک نہیں ہے اور بالیقین محمد صلی اللہ علیہ وسلم اللہ کے بندے اور اس کے رسول ہیں، اے نبی! آپ پر سلامتی ہو اور اللہ کی رحمت اور برکت نازل ہو۔ سلامتی نازل ہو ہم پر اور اللہ کے تمام نیک بندوں پر سلامتی ہو تم پر۔‘‘","",{"k":"مؤطا (206) -"}],[1542,"عبدالرحمن بن عبدالقاری سے روایت ہے اس نے عمر رضی اللہ عنہ سے سنا، وہ منبر پر لوگوں کو تشہد کی تعلیم دیتے تھے۔ کہتے تھے: کہو! تمام عبادات اللہ تعالیٰ کے لیے ہیں، پاکیزہ صدقات اللہ کے لیے ہیں، عمدہ نمازیں اللہ کے لیے ہیں، سلامتی ہے آپ پر اے نبی کریم!۔۔۔۔۔ابن مسعود رضی اللہ عنہ کے تشہد کے آخر تک۔","",{"k":"مؤطا (204) -"}],[1543,"سیدنا ابن مسعود رضی اللہ عنہ کہا کرتے تھے: تشہد کو خفیہ پڑھنا سنت ہے۔","",{"k":"ترمذی (238)، صحیح، البانی: 237، ابوداؤد (986).","e":"......۱۔ نسائی والی حدیث میں جو تشہد سے پہلے بسم اللہ کا اضافہ ہے یہ صحیح نہیں۔ (مقاصد للسخاوی: ۶۹) طبرانی والی روایات صحیح طور پر ثابت نہیں، لہٰذا دعاؤں کے متعلق کچھ کہا نہیں جا سکتا۔ علامہ زرقانی رحمہ اللہ بھی یہی فرماتے ہیں، جو ہم نے اوپر لکھا ہے کہ جتنے بھی صحابہ کرام رضی اللہ عنہم سے تشہد روایت ہوا ہے، ان میں سے جو صحیح روایت میں آیا ہے، اسے پڑھنا جائز ہے مگر سیدنا عبداللہ بن مسعود رضی اللہ عنہ والا تشہد سب سے زیادہ صحیح ہے اور افضل ہے۔ (شرح موطا: ۱/۱۸۷) اور جو موطا کے حوالہ سے تشہد آئے ہیں، یہ تو موقوف ہیں صحابی رضی اللہ عنہ سے ثابت ہیں ان پر تو ابن مسعود رضی اللہ عنہ والے تشہد کو زیادہ ترجیح ہوگی۔ ۲۔ نسائی میں تشہد کے ساتھ جو آخر میں اضافہ آیا ہے وہ بھی ضعیف ہے لہٰذا اس سے بھی احتراز کیا جائے۔ تشہد عبدہ ورسولہ تک ہی رکھا جائے۔ ۳۔ صحابی رضی اللہ عنہ جب یہ کہیں کہ یہ کام سنت ہے تو یہ نبی صلی اللہ علیہ وسلم کا فرمان ہوتا ہے۔ ترمذی کی اس حدیث میں دلیل ہے کہ تشہد نماز میں آہستہ آواز سے پڑھا جائے۔"}],[1544,"سیدنا ابوسعید رضی اللہ عنہ مرفوع حدیث بیان کرتے ہیں: ’’نماز کی کنجی طہارت ہے اور اس کی حرمت تکبیر ہے اور اس کی حلت سلام سے ہے اور اس کی نماز جائز نہیں جس نے سورت الفاتحہ اور کوئی سورت تلاوت نہ کی خواہ نماز فرض ہو یا غیر فرض ہو۔‘‘ (ترمذی)","",{"k":"ترمذی (238)، صحیح، البانی: 198، ابن ماجہ (276).","e":"......۱۔ اس حدیث میں یہ بیان ہوا ہے کہ نماز کا دروازہ بندہ صرف وضو کی کنجی سے ہی کھول سکتا ہے اس کے بغیر نماز نہیں ہوتی۔ ۲۔ نماز میں جو کام بھی حرام ہیں اور نماز کے منافی ہیں اور ان پر دوران نماز پابندی ہے وہ تکبیر تحریمہ کے بعد ممنوع ہو جاتے ہیں۔ اللہ اکبر کہنا نماز میں داخلہ ہے اور نماز سے فراغت سلام پھیرنے سے ہوتی ہے۔ ۳۔ بظاہر اس حدیث سے معلوم ہوتا ہے کہ نماز میں جس طرح سورت فاتحہ فرض ہے، اس کے ساتھ اس سے زائد پڑھنا بھی فرض ہے۔ ہم قراءت کے باب میں وضاحت کر چکے ہیں کہ سورت فاتحہ فرض ہے اس سے زائد قراءت کریں تو ثواب ہے اگر صرف سورت فاتحہ ہی پڑھ لیں تو کافی ہے۔ اس کی تائید سیدنا عبادہ بن صامت رضی اللہ عنہ کی حدیث بھی کرتی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’سورت فاتحہ دوسری قراءت کا عوض بن جاتی ہے، دوسری قراءت سورت فاتحہ کا عوض نہیں ہوسکتی۔ (دارقطنی) اس کی روشنی میں اس حدیث کی تاویل یہی ہوگی کہ سورت فاتحہ فرض ہے۔ نماز میں اس کے علاوہ قراءت فرض نہیں اگر کوئی پڑھ لیتا ہے تو ثواب ہے۔ ۴۔ یہ حدیث نماز میں داخل اور خارج ہونے کا طریقہ متعین کر رہی ہے۔ مگر بعض حضرات کا خیال ہے کہ نماز کے لیے اللہ تعالیٰ کا کوئی بھی نام لیں اور داخل ہوں تو درست ہے اور نماز کے خلاف کوئی بھی طریقہ اپنائیں مثلاً قہقہ لگائیں یا ہوا خارج کریں تو نماز سے فارغ ہو جائیں گے۔ اس حدیث میں اس موقف کی سخت تردید ہے۔ علامہ عبدالرحمن مبارک پوری رحمہ اللہ فرماتے ہیں: اَلْحَقُّ فِي هَذَا الْبَابِ مَا ذَهَبَ إِلَيْهِ الْجُمْهُورُ مِنْ أَنَّ تَحْرِيمَ الصَّلَاةِ التَّكْبِيرُ وَلَا يَكُونُ الرَّجُلُ دَاخِلًا فِي الصَّلَاةِ إِلَّا بِالتَّكْبِيرِ. (تحفة الاحوذی: ۱/۲۰۰) ’’اس بارے میں حق بات یہی ہے کہ نماز میں آدمی کا داخلہ فقط تکبیر تحریمہ کے ذریعے ہی ہے، اس کے علاوہ کسی چیز سے نہیں۔‘‘ یہی صورت نماز سے فارغ ہونے کی ہے کہ فقط سلام سے ہی فراغت ہوتی ہے۔"}],[1545,"نافع کہتے ہیں کہ سیدنا ابن عمر رضی اللہ عنہما نماز میں انگلی سے اشارہ کرتے اور انگلی پر نظر جمائے رکھتے اور انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے انگلی کا اشارہ شیطان پر لوہے سے زیادہ شدید ہے۔ (البزار اور احمد نے کمزور سند سے روایت کیا)","",{"k":"بزار اور احمد (5964)، وفیہ کثیر بن زید وثقہ ابن حبان، وضعفہ غیرہ علاوہ ازیں مسلم (580)، ترمذی (294)، نسائی (1269)، ابوداؤد (987)، ابن ماجہ (913)، مؤطا (199)، دارمی (1339).","e":"......تشہد میں اشارہ توحید کے الفاظ پر کیا جاتا ہے اور توحید ایک ایسی باعث برکت چیز ہے اس سے شیطان کی امیدوں پر پانی پھر جاتا ہے، یہ شیطان اس نمازی کو کفر و شرک میں مبتلا کرنے سے مایوس ہو جاتا ہے اس لیے یہ اشارہ انگشت اس پر تیر و تلوار بن کر برستا ہے۔"}],[1546,"اسود رحمہ اللہ کہتے ہیں: ابن مسعود رضی اللہ عنہ ہمیں نماز کا تشہد تعلیم کرتے اور الف اور واؤ کی غلطی پر بھی گرفت کرتے تھے۔ (البزار)","",{"k":"بزار، وفی اسناد الطبرانی زہیر بن مروان الرقاشی ولم اجد من ذکرہ، واسناد البزار رجالہ رجال الصحیح، ہیثمی: 2852."}],[1547,"سیدنا ابن مسعود رضی اللہ عنہ سے روایت ہے کہ ہم نے کہا وہ نبی کریم صلی اللہ علیہ وسلم سے تشہد اسی طرح حفظ کیے ہوئے ہیں جیسے قرآن کے حروف حفظ کیے ہیں واؤات بھی اور الفات بھی۔ یعنی تمام واؤ اور تمام الف۔‘‘","",{"k":"طبرانی کبیر."}],[1548,"’’البہزی سے روایت ہے کہ میں نے حسین بن علی رضی اللہ عنہما سے علی رضی اللہ عنہ کے تشہد کے متعلق سوال کیا تو حسین رضی اللہ عنہ نے کہا: علی رضی اللہ عنہ کا تشہد وہی تھا جو رسول اللہ صلی اللہ علیہ وسلم کا تشہد تھا: تمام عبادات، پاکیزہ صدقات، صبح و شام کی نہایت پاکیزہ اور نہایت بابرکت پاکیزہ عبادات سب اللہ ہی کے لیے ہیں۔‘‘ (الکبیر اور الاوسط)","",{"k":"طبرانی کبیر: 2905، طبرانی اوسط، ورجاله الكبير موثقون، هيثمي: 2857."}],[1549,"اور اس میں یہ کلمات بھی ہیں: ’’نہایت نفیس اور بھر پور عبادات۔‘‘","",{"k":"طبرانی کبیر ورجاله الكبير موثقون."}],[1550,"’’ابو الورد سے روایت ہے وہ کہتے ہیں کہ انہوں نے عبداللہ بن زبیر کو کہتے سنا: نبی صلی اللہ علیہ وسلم کا تشہد یہ ہے: ’’اللہ کے نام سے اور اللہ کے ساتھ جو بہتر ہے اسماء کا ......... عبادات پاکیزہ، صفات اور نمازیں اللہ ہی کے لیے ہیں۔ میں گواہی دیتا ہوں کہ کوئی معبود نہیں اللہ کے سوا، وہ ایک ہے اس کا کوئی شریک نہیں ہے اور یہ کہ محمد صلی اللہ علیہ وسلم اللہ کے بندے اور اس کے رسول ہیں۔ اللہ تعالیٰ نے ان کو حق کے ساتھ بشارت دینے اور ڈرانے والا بنا کر ارسال فرمایا ہے۔ اور قیامت آنے والی ہے اور اس میں کوئی شک نہیں ہے، سلامتی ہو آپ پر اے نبی کریم! اور اللہ کی رحمت اور اس کی برکات ہوں۔ سلامتی ہو ہم پر اور اللہ تعالیٰ کے تمام نیک بندوں پر۔ اے اللہ! مجھے بخش اور مجھے ہدایت عطا کر۔‘‘ (البزار اور الکبیر سند کمزور ہے)","",{"k":"بزار اور طبرانی کبیر، ومداره على ابن لهيعة وفيه كلام.","e":"...... اس مفہوم کی روایات پر پہلے وضاحت گزر چکی ہے، دوبارہ ملاحظہ فرما لیں۔"}],[1551,"سیدنا ابن مسعود رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم دائیں اور بائیں طرف سلام پھیرتے تھے: ’’سلامتی ہو تم پر اور اللہ کی رحمت نازل ہو، سلامتی ہو تم پر اور اللہ کی رحمت نازل ہو۔‘‘","",{"k":"ترمذی (295)، صحيح، البانی: 241، ابوداؤد (296)، ابن ماجه (914)، احمد (4268)."}],[1552,"نسائی نے یہ زائد بیان کیا ہے: یہاں تک کہ آپ صلی اللہ علیہ وسلم کی رخسار مبارک کی سفیدی دیکھی جاتی اس جگہ سے اس رخسار مبارک کی سفیدی دیکھی جاتی اس جگہ سے۔‘‘","",{"k":"نسائی (1324)، صحيح، البانی: 1256"}],[1553,"سیدنا سمرہ بن جندب رضی اللہ عنہ سے روایت ہے کہ اما بعد! ہمیں حکم دیا رسول اللہ صلی اللہ علیہ وسلم نے کہ ہم نماز کے درمیان میں بھی اور نماز کے آخر میں بھی سلام سے پہلے ہوں تو فرمایا: کہو: تمام پاکیزہ عبادتیں اور نماز اور ملک و حکومت اللہ تعالیٰ کے لیے ہے اور پھر اپنے قاری پر اور اپنے اوپر سلام کہو۔‘‘ (ابو داؤد)","",{"k":"ابوداؤد (975)، ضعيف، البانی: 206."}],[1554,"سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت ہے کہ جب ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز ادا کرتے تو ہم کہتے: السلام علیکم ورحمۃ اللہ، السلام علیکم ورحمۃ اللہ اور انہوں نے اپنے ہاتھ سے دو طرف اشارہ کیا (اور بتایا) پس رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم اپنے ہاتھوں سے اشارہ کس وجہ سے کرتے ہو گویا شریر گھوڑوں کی دم ہلتی ہے۔ تمہارے لیے یہ امر کفایت کرتا ہے کہ کوئی شخص تم میں سے اپنا ہاتھ ران پر ہی رہنے دے اور اپنے بھائی کو دائیں بائیں سلام کہے۔‘‘ (مسلم، ابو داؤد، نسائی)","",{"k":"مسلم (431)، نسائی (1326)، ابوداؤد (1000)، احمد (20522)."}],[1555,"اور اس کی ایک روایت ہے: بلا شبہ تم میں سے ہر ایک کے لیے یہ امر کفایت کرتا ہے کہ وہ اس طرح کرے اور انگلی سے اشارہ کر کے بتایا کہ سلام کہے اپنے بھائی پر اپنے دائیں طرف اور اپنے بائیں طرف۔","",{"k":"ابوداؤد (998)، صحيح، البانی: 881، ابوداؤد (1000)، احمد (20522)."}],[1556,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم صرف اپنے منہ کے سامنے ایک ہی بار سلام کہتے تھے اور پھر تھوڑا تھوڑا سا دائیں طرف کو مائل ہو جاتے تھے۔ (ترمذی)","",{"k":"ترمذی (296)، صحيح، البانی: 242، ابن ماجه (919)."}],[1557,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ سلام کرنا سنت ہے۔ (ترمذی اور ابو داؤد)","",{"k":"ترمذی (297)، ضعيف: 48، ابوداؤد (1004)، احمد (10504).","e":"...... ۱۔ نبی اکرم صلی اللہ علیہ وسلم نے صحابہ کرام رضی اللہ عنہم کی تشہد کی کوتاہی کی نشاندہی فرمائی ہے۔ وہ تشہد میں دائیں اور بائیں سلام پھیرتے ہوئے ساتھ ہاتھوں کے اشارے کرتے تھے نبی صلی اللہ علیہ وسلم نے فرمایا کہ دایاں ہاتھ دائیں ران پر ہی رہنے دو۔ اور بایاں ہاتھ بائیں ران پر ہی رہنے دو اور سلام پھیرو۔ اس حدیث نے ان لوگوں کے نظریے کی تردید کر دی ہے جو کہتے ہیں کہ اس سے رفع یدین منسوخ ہوئی ہے یہ تو معاملہ ہی تشہد کا ہے، رفع یدین کا اس سے تعلق نہیں۔ تشہد میں آپ نے ہاتھوں کو رانوں پر رکھنے کا کہا تھا۔ ۲۔ ان سے یہ بھی پتہ چلتا ہے کہ نبی صلی اللہ علیہ وسلم دائیں اور بائیں جانب سلام پھیرنے میں اچھی طرح مڑتے تھے، اچھی طرح مڑیں تو تب ہی رخسار نظر آتے ہیں۔ ۳۔ یہ بھی ثابت ہوا کہ نماز میں سلام دونوں طرف پھیرنا سنت ہے اور صرف ایک طرف ہی سلام پھیرنے کے متعلق ایک گروہ کی یہ تحقیق ہے کہ یہ تمام احادیث جن میں ایک طرف سلام پھیرنے کا آتا ہے، وہ ضعیف ہیں۔ (نصب الرایہ)\nان کے نزدیک تو ایک طرف سلام پھیرنا ثابت نہ ہوا یہ دونوں طرف سلام پھیرنے کا ہی کہتے ہیں کہ دائیں طرف نماز کا سلام فرض ہے دوسری طرف کا سلام سنت ہے۔ مگر سلام پھیرنا دو طرف ہے۔ اور یہ کہتے ہیں اگر یہ ثابت بھی ہو کہ ایک طرف سلام تھا تو اس کی تاویل یہ ہوگی کہ بلند آواز سے آپ نے سنایا ایک طرف ہے، دوسری طرف سلام پھیرا تھا مگر اتنا بلند آواز میں نہ تھا۔ جن کے نزدیک ایک طرف سلام پھیرنے والی روایات ثابت ہیں۔ وہ کہتے ہیں، کبھی کبھار جواز کے لیے نبی اکرم صلی اللہ علیہ وسلم نے ایک طرف سلام پھیرا تھا، اکثر معمول آپ صلی اللہ علیہ وسلم کا دونوں طرف سلام پھیرنے کا ہی تھا۔ دونوں طریقے سنت ہیں۔ راقم کے نزدیک محتاط یہی رائے ہے کہ اکثر طور پر آپ صلی اللہ علیہ وسلم کا معمول مبارک دونوں طرف سلام پھیرنے کا تھا، کبھی جواز کے لیے آپ نے ایک ہی سلام پر اکتفا کیا ہے۔ ۴۔ عام روایات میں تو نماز سے فراغت کے لیے یہی الفاظ ہیں۔ السلام علیکم ورحمۃ اللہ مگر بعض روایات میں رحمۃ اللہ کے بعد و برکاتہ کے الفاظ بھی وارد ہوئے ہیں۔ (التلخیص الحبیر: ۱/۱۰۴) ۵۔ اس میں اس نظریے کی تردید بھی ہے کہ سلام پھیرنے کی جگہ کوئی بھی نماز کے منافی کام کر دیں تو فراغت ہو جاتی ہے۔ اس سے ثابت ہوتا ہے کہ نماز سے فراغت کے لیے فقط سلام ہے اور کوئی چیز اس کے قائم مقام نہیں ہو سکتی۔ یہ لوگ جو بھی دلائل دیتے ہیں علامہ عبید اللہ رحمانی رحمہ اللہ ان کے متعلق فرماتے ہیں یہ سب ضعیف ہیں، صحیح بات یہی ہے کہ نماز سے فراغت فقط سلام پھیرنے سے ہی ہوتی ہے اور کسی طرح جائز نہیں۔ (مرعاۃ: ۲/۵۳۶)"}],[1558,"عائشہ رضی اللہ عنہا سے مرفوع حدیث مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم سلام پھیرتے تو صرف اس قدر ہی بیٹھتے جس قدر یہ کلمات کہتے: اے اللہ! تو سلامتی دینے والا ہے، سلامتی تیری طرف سے ہے، تو برکت والا ہے اور اے عزت والے! کرم کرنے والے۔‘‘ (مسلم و ترمذی)","",{"k":"ترمذی (298)، صحيح، البانی: 243، مسلم (592)، نسائی (1338)، ابوداؤد (1512)، ابن ماجه (1993)، احمد (23817)، دارمی (1347).","e":"...... آپ صلی اللہ علیہ وسلم نے نماز فرض سے سلام پھیرنے کے بعد بعض اوقات حدیث میں درج دعا پڑھنے تک بیٹھتے تھے یعنی اتنی مقدار قبلہ رخ ہی رہتے یہ پڑھ لیتے تو پھر دائیں یا بائیں مڑتے اور مقتدیوں کی جانب منہ کر لیتے۔ ۲۔ علامہ عبید اللہ رحمانی فرماتے ہیں کہ اس دعا میں وَإِلَيْكَ يَرْجِعُ السَّلَامُ فَحَيِّنَا رَبَّنَا بِالسَّلَامِ وَأَدْخِلْنَا دَارَ السَّلَامِ کا جو اضافہ ہے، یہ بے اصل ہے۔ (مرعاۃ: ۲/۵۵۵)\n۳۔ سلام اللہ تعالیٰ کے اسمائے گرامی میں سے ہے یعنی اے اللہ! تو ہر عیب اور آفت سے سلامتی والا ہے۔ اور جو بھی انسانوں کو سلامتی ملی ہے وہ تو ہی عطا کرتا ہے۔ لہذا دنیا و آخرت کی تمام آفات اور شرارتوں سے ہم تجھ ہی سے سلامتی کے طلب گار ہیں۔ جو بھی برکت ہے وہ تیری جلالت و کرامت ہی کی بدولت ملتی ہے۔"}],[1559,"واسع بن حبان نے کہا: میں نماز پڑھ رہا تھا اور ابن عمر رضی اللہ عنہما کعبہ کی دیوار سے تکیہ لگا کر بیٹھے تھے۔ جب میں نے نماز پوری کی تو بائیں طرف منہ کر کے اس کی طرف متوجہ ہوا۔ تو انہوں نے کہا: کس وجہ سے تو دائیں طرف منہ پھیر کر نہیں بیٹھا؟ میں نے کہا: میں نے تجھے دیکھا تو تیری طرف منہ پھیر کر بیٹھا ہوں۔ انہوں نے کہا: تو نے درست کیا۔ کوئی کہنے والا کہتا ہے دائیں طرف ہی منہ پھیرا کرو۔ تو جب تو نماز پڑھے تو جس طرف چاہے منہ پھیرا کر، اگر تو چاہے تو دائیں طرف اور تو چاہے تو اپنے دائیں طرف منہ پھیر دے۔‘‘ (مالک)","",{"k":"مؤطا (409)."}],[1560,"سیدنا ابن مسعود رضی اللہ عنہ کا قول ہے: تم میں سے کوئی شخص اپنی نماز میں شیطان کا حصہ نہ لگائے کہ وہ یہ گمان کرتا ہو کہ اس پر یہ حق لازم ہے کہ وہ صرف دائیں طرف ہی نماز سے منہ پھیر کر بیٹھے۔ میں نے بکثرت دیکھا ہے کہ رسول اللہ صلی اللہ علیہ وسلم بائیں طرف منہ مبارک پھیرا کرتے تھے۔","",{"k":"بخاری (852)، مسلم (707)، نسائی (1360)، ابوداؤد (1042)، ابن ماجه (930)، احمد (4412)، دارمی (1350).","e":"...... ان احادیث سے ثابت ہوتا ہے کہ امام مقتدیوں کی طرف منہ پھیرے اور جس جس طرح حدیث سے ثابت ہے، اس طرح منہ پھیرنا جائز ہے۔ صحیح ترین حل یہ ہے کہ امام اگر سلام کے بعد بیٹھنا نہیں چاہتا اپنے گھر جانا چاہتا ہے تو ضرورت کے مطابق دائیں یا بائیں مڑ جائے اور گھر چلا جائے۔ اگر امام نماز کے بعد ہی اپنی جائے نماز پر بیٹھنا چاہتا ہے تو پھر سنت یہ ہے کہ اپنے تمام مقتدیوں کی طرف منہ کرے صرف دائیں یا بائیں والوں کی طرف ہی نہ کرے۔ ہر صورت دائیں پھرنے اور بائیں پھرنے میں جواز ہے، دونوں طرح جائز ہے اس میں کراہت نہیں۔ سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے اسے غلط قرار دیا ہے جو فقط دائیں جانب ہی مڑنا واجب سمجھتا ہے۔ ضرورت کے مطابق دائیں یا بائیں مڑ جائے اور گھر وغیرہ میں چلا جائے اگر مسجد میں ہی ٹھہرتا ہے تو پھر دائیں یا بائیں سے پھرے مگر رخ تمام مقتدیوں کی طرف کرنا ہے۔ (فتح الباری: ۲/۳۳۸)"}],[1561,"عمرو سے روایت ہے کہ ابو معبد ابن عباس رضی اللہ عنہ کے غلام نے انہیں خبر دی کہ ابن عباس رضی اللہ عنہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں جب فرض نماز سے سلام پھیرتے تو لوگ بلند آواز سے ذکر کرتے تھے، میں جب سنتا تو مجھے معلوم ہو جاتا کہ اب نماز سے سلام پھیرا ہے۔","",{"k":"بخاری (841)، مسلم (583)، نسائی (1335)، ابوداؤد (1003)، احمد (3468)."}],[1562,"سیدنا عبداللہ بن عباس رضی اللہ عنہما فرماتے ہیں: ہم نبی کریم صلی اللہ علیہ وسلم کی نماز مکمل ہونے کو صرف تکبیر کے سبب ہی جانتے تھے۔","",{"k":"مسلم (583)، نسائی (1335)، ابوداؤد (1003)، احمد (3468).","e":"...... یہ حدیث اس بات پر دلیل ہے کہ فرض نماز کے سلام کے بعد اللہ اکبر کہنا اور دیگر مسنون اذکار بلند آواز سے کرنے جائز ہیں۔ جیسا کہ ابن حزم رحمہ اللہ نے محلی میں لکھا ہے۔ (۴/۲۶۰) اس حدیث میں اس موقف کی تردید ہے جو کہتے ہیں کہ اللہ اکبر اور اذکار فرض نماز کے بعد پوشیدہ ہوں۔"}],[1563,"سیدنا زید بن ارقم رضی اللہ عنہ سے روایت ہے کہ ہم نماز میں کلام کیا کرتے تھے۔ ایک شخص اپنے ساتھ والے شخص کے ساتھ کلام کرتا تھا تا آنکہ یہ آیت نازل ہوئی: کھڑے ہوا کرو اللہ کے لیے فرماں بردار ہو کر۔ پس خاموش رہنے کا حکم دیا گیا اور کلام کرنے سے منع کیا گیا۔","",{"k":"مسلم (539)، بخاری (4534)، ترمذی (2986)، نسائی (1219)، ابوداؤد (949)، احمد (18792)."}],[1564,"سیدنا ابن مسعود رضی اللہ عنہ نے کہا: ہم نماز میں نبی کریم صلی اللہ علیہ وسلم کو سلام کہا کرتے تھے اور آپ صلی اللہ علیہ وسلم بھی ہمیں جواب دیتے تھے۔ جب ہم نجاشی کے پاس سے واپس آئے تو ہم نے آپ صلی اللہ علیہ وسلم کو سلام کیا، پس آپ صلی اللہ علیہ وسلم نے سلام کا جواب نہ دیا۔ تو ہم نے عرض کیا: یا رسول اللہ! ہم جب آپ صلی اللہ علیہ وسلم کو نماز میں سلام کہتے تھے تو آپ سلام کا جواب دیا کرتے تھے، فرمایا: ’’نماز میں شغل ہوتا ہے۔‘‘","",{"k":"بخاری (3875)، مسلم (538)، نسائی (1221)، ابوداؤد (924)، ابن ماجه (1019)، احمد (4403)."}],[1565,"اور اس کی ایک روایت ہے: میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں واپس آیا تو آپ صلی اللہ علیہ وسلم نماز پڑھ رہے تھے، میں نے آپ صلی اللہ علیہ وسلم کو سلام کیا تو آپ صلی اللہ علیہ وسلم نے میرے سلام کا جواب نہ دیا، پس مجھے پرانے اور نئے تمام حالات یاد آ گئے۔ جب آپ صلی اللہ علیہ وسلم نے نماز مکمل کی تو فرمایا: ’’اللہ جب چاہے جدید حکم نازل فرماتا ہے اور جو نئے احکام نازل کیے ہیں ان میں سے یہ بھی ہے کہ نماز میں کلام نہ کیا کرو۔‘‘ اس کے بعد آپ صلی اللہ علیہ وسلم نے مجھے سلام کا جواب دیا۔","",{"k":"ابوداؤد (924)، حسن، صحیح، 817، ابن ماجه (1019)، احمد (4403).","e":"...... ۱۔ اس میں پہلے یہ بات ذہن نشین کر لیں کہ صحابہ کرام رضی اللہ عنہم کی ایک جماعت نے سرزمین مکہ سے حبشہ کی جانب ہجرت کی تھی کہ دین محفوظ رہے اور فتنہ سے بچیں۔ حبشہ میں رہنے والے مہاجروں کو یہ اطلاع ملی کہ مشرک اسلام لے آئے ہیں، مگر جب وہ واپس مکہ آئے تو معاملہ اس کے برعکس تھا، بلکہ یہ مشرک مسلمانوں پر تشدد میں اور سخت ہو چکے تھے۔ تو یہ دوبارہ حبشہ میں چلے گئے۔ سیدنا ابن مسعود رضی اللہ عنہ بھی ان میں شامل ہیں جو مکہ سے حبشہ گئے تھے اور مکہ والوں کے اسلام کی اطلاع پا کر حبشہ سے مکہ آئے تھے اور دوبارہ پھر حبشہ چلے گئے۔ ادھر جب رسول اکرم صلی اللہ علیہ وسلم نے مدینہ منورہ کی جانب ہجرت کی تو حبشہ کے مہاجروں میں سے اب کچھ لوگ مدینہ منورہ ہجرت کر کے آ گئے، سیدنا عبداللہ بن مسعود رضی اللہ عنہ بھی ان میں سے تھے۔ یہ جو سیدنا ابن مسعود رضی اللہ عنہ نے کہا ہے کہ جب ہم لوٹے، اس سے مراد یہی ہے کہ جب ہم حبشہ سے ہجرت کر کے مدینہ منورہ میں لوٹے تو نماز میں خاموشی کا حکم آیا۔ ۲۔ سیدنا زید بن ارقم رضی اللہ عنہ کا کہنا کہ ہم نماز میں بات کر لیتے تھے پھر ہمیں خاموشی کا حکم ہوا۔ اسے اور سیدنا ابن مسعود رضی اللہ عنہ والی روایت کو ملا کر مطلب یہ اخذ ہوتا ہے کہ نماز میں بات کرنا مکہ میں بھی جائز تھا اور ہجرت کے بعد بھی تھوڑی دیر جائز رہا۔ جب سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے آئے تو اس پر پابندی لگ چکی تھی۔ اس لیے وہ حیران ہوئے۔ ۳۔ ان احادیث سے ثابت ہوا کہ اب نمازی کو سلام کہنا جائز ہے مگر نمازی اس کا جواب بول کر نہ دے، اب بات کا یا سلام کا جواب منع ہے، وہ سلام کا جواب اشارہ سے دے سکتا ہے۔"}],[1566,"سیدنا معاویہ بن حکم رضی اللہ عنہ سے روایت ہے میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھ رہا تھا کہ لوگوں میں سے ایک آدمی کو چھینک آئی تو میں نے کہا: یرحمک اللہ (اللہ تیرے اوپر رحم فرمائے) تو لوگوں نے مجھے آنکھوں سے گھورنا شروع کر دیا، پس میں نے کہا: وائے تمہاری مائیں تمہیں گم کر دیں، تمہارا کیا مقصد ہے کہ تم مجھے دیکھتے ہو؟ تو لوگوں نے اپنے ہاتھ اپنی ران پر مارنے شروع کر دیے، پس میں نے یہ خیال کیا کہ وہ مجھے خاموش کرنا چاہتے ہیں تو میں خاموش ہو گیا۔ جب نبی کریم صلی اللہ علیہ وسلم نماز پڑھ چکے تو میرے ماں باپ آپ صلی اللہ علیہ وسلم پر فدا ہوں میں نے آپ صلی اللہ علیہ وسلم سے پہلے اور آپ کے بعد کوئی معلم آپ سے بہتر تعلیم دیتا نہیں دیکھا۔ قسم اللہ کی! نہ مجھے ڈانٹا، نہ مارا اور نہ گالی دی۔ صرف یہ فرمایا: نماز میں لوگوں سے کلام کرنا جائز نہیں ہے اور نہ لوگوں جیسی بات چیت جائز ہے۔ نماز تو صرف تسبیح پڑھنے، تکبیر کہنے اور قرآن کی تلاوت کرنے سے عبارت ہے۔ یا جیسا آنحضرت صلی اللہ علیہ وسلم نے فرمایا۔ میں نے عرض کی: یا رسول اللہ! میں نیا نیا جاہلیت سے باہر آیا ہوں اور اب اللہ تعالیٰ اسلام میں لے آیا ہے۔ اور ہم میں سے کچھ لوگ غیب کی خبر بتانے والوں (کہانوں) کے پاس جاتے ہیں۔ فرمایا: تو ہرگز نہ جایا کر۔ میں نے عرض کی: کچھ لوگ بدفالی لیتے ہیں۔ فرمایا: یہ صرف ان کے سینوں میں وسوسے پیدا ہوتے اور وہ ان کو کسی کام سے باز نہ رکھیں، سائل نے کہا: کچھ لوگ ہمیں خطوط اور لکیریں لکھتے ہیں۔ فرمایا: ایک نبی لکیر اور خط لکھتے تھے۔ تو جس نے اس کے موافق لکھا تو وہ درست ہو گا۔ اس نے کہا: میری ایک لونڈی احد اور جوانیہ دو مقامات کی اطراف میں بکریاں چرایا کرتی تھی، ایک دن میں نے جا کر بکریاں دیکھیں تو ہماری بکریوں میں سے ایک بکری کو بھیڑیا اٹھا کر لے جا چکا تھا۔ میں بھی اولاد آدم میں سے ایک انسان ہوں مجھے افسوس لگا جیسا انسانوں کو لگتا ہے۔ تو میں نے اس لونڈی کو ایک تھپڑ رسید کر دیا۔ میں نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ تو آپ صلی اللہ علیہ وسلم نے میرے اوپر یہ بڑا جرم قرار دیا تو میں نے عرض کی یا رسول اللہ صلی اللہ علیہ وسلم! میں اس لونڈی کو آزاد ہی نہ کردوں؟ فرمایا: اس کو میرے پاس لاؤ۔ میں آپ صلی اللہ علیہ وسلم کے پاس لایا تو آپ نے اس کو فرمایا: اللہ تعالیٰ کہاں ہے؟ اس نے کہا: آسمان میں ہے۔ فرمایا: میں کون ہوں؟ اس نے کہا: آپ صلی اللہ علیہ وسلم اللہ کے رسول ہیں۔ فرمایا: ’’اس کو آزاد کر دو یہ ایماندار عورت ہے۔‘‘ (مسلم، ابو داؤد، نسائی)","",{"k":"مسلم (537)، نسائی (1218)، ابوداؤد (3909)، احمد (23256)، دارمی (1502).","e":"...... ۱۔ سیدنا معاویہ بن حکم رضی اللہ عنہ نماز میں تھے، ایک آدمی کو چھینک آئی تو اس نے الحمد للہ کہا، اس کے جواب میں انہوں نے یرحمک اللہ کہا۔ ثابت ہوا چھینک مارنے کے لیے نماز میں الحمد للہ کہنا جائز ہے اور سننے والے کو یرحمک اللہ نہیں کہنا چاہیے۔\n۲۔ یہ کہنا چونکہ درست نہ تھا، صحابہ کرام رضی اللہ عنہم نے ان کی طرف اشارتاً نظروں سے اس سے روکا تو انہوں نے اور بولنا شروع کر دیا تو صحابہ کرام رضی اللہ عنہم نے ان کی نادانی کے پیش نظر رانوں پر ہاتھ مار کر سخت احتجاج کیا، یہ تھے تو بہت غصہ میں مگر خاموشی اختیار کی۔ نماز سے فراغت ہوئی تو نبی اکرم صلی اللہ علیہ وسلم سیدنا معاویہ رضی اللہ عنہ کی اس نادانی پر نہ تو طیش میں آئے نہ برا بھلا کہا، نہ ہی ڈانٹا۔ بلکہ کمال لطف و احسان کا مظاہرہ فرمایا اور ان کی رہنمائی کی۔ ۳۔ اس حدیث سے یہ ثابت ہوتا ہے کہ نماز میں چھینک مارنے والا الحمد للہ کہے تو جائز ہے اس کا جواب دینا جائز نہیں۔ یہ لوگوں کی عام گفتگو کے ضمن میں آتا ہے جو کہ جائز نہیں۔ جو قصداً کہے اس کی نماز خراب ہو جاتی ہے۔ اگر بھول کر کہے تو نماز خراب نہیں ہوتی، یہ بھی ثابت ہوا نماز میں ہاتھوں کی چھوٹی موٹی حرکت سے نماز میں فرق نہیں آتا۔ ۴۔ کاہن جو کہ غیب کی باتیں بتانے کا دعویدار ہے اور نجومی جو علم نجوم کے ذریعے قسمتوں کا حال بتاتا ہے، چونکہ ان کے پاس جانے سے انسان فتنہ میں واقع ہو جاتا ہے۔ ان کے پاس جانے کی سخت ممانعت ہے۔ ۵۔ اس میں بدشگونی پکڑنے سے ممانعت آئی ہے، یہ جاہلیت میں بھی اور آج بھی رائج ہے، دیکھا کہ پرندہ یا جانور دائیں جانب جاتا ہے تو وہ کام کرتا اور اگر دیکھا کہ یہ بائیں جانب چلا ہے تو اسے محرومی قسمت تصور کرتے۔ اس کا چونکہ حقیقت سے معمولی بھی تعلق نہیں تھا، محض وہم تھا، اس لیے اس پر پابندی لگا دی گئی۔ ۶۔ ریت پر لکیروں کے ذریعے بھی قسمت آزمائی سے منع کیا گیا ہے، ریت پر بہت ساری لکیریں بناتے تھے اور مٹاتے جاتے تھے اگر دورہ جاتیں تو کامیابی سمجھتے اگر ایک رہ جاتی تو اسے ناکامی سمجھتے۔ علم جعفر والے اس سے دلیل لیتے ہیں کہ یہ جائز ہے کیونکہ دانیال یا اور میں نبی کرتے تھے۔ مگر یہ دلیل درست نہیں کیونکہ آپ صلی اللہ علیہ وسلم نے دراصل اس سے روکا ہے کیونکہ ہمیں پتہ نہیں وہ نبی کیسے لکیریں بناتے تھے، جس چیز کا علم نہیں وہ جائز کیسے ہوسکتی ہے۔"}],[1567,"عمرو بن میمون سے حدیث مروی ہے کہ نبی صلی اللہ علیہ وسلم نے معاذ بن جبل رضی اللہ عنہ کو یمن کی طرف روانہ کیا تو انہوں نے فجر کی نماز میں سورت النساء تلاوت کی اور جب اس نے یہ آیت تلاوت کی: ’’اللہ تعالیٰ نے ابراہیم کو اپنا دوست بنایا ہے۔‘‘ تو پیچھے سے ایک مرد نے کہا: ابراہیم علیہ السلام کی ماں کی آنکھیں ٹھنڈی ہوئیں۔ (بخاری)","",{"k":"بخاری (4348).","e":"......۱۔ سیدنا معاذ رضی اللہ عنہ کو نبی اکرم صلی اللہ علیہ وسلم نے نماز اور زکوٰۃ کا امیر بنا کر بھیجا تھا کیونکہ سیدنا ابن عباس رضی اللہ عنہما والی حدیث میں زکاۃ پر امیر بنانے کا آتا ہے ہم نے اوپر مطابقت بیان کر دی ہے۔ ۲۔ یہ جو کہا ہے کہ حضرت ابراہیم علیہ السلام کو خلیل اللہ بنا کر اللہ تعالیٰ نے حضرت ابراہیم علیہ السلام کی والدہ کی آنکھیں ٹھنڈی کی تھیں اس سے مراد ہے کہ مسرت سے نوازا تھا کہ بیٹے کو اتنا بڑا رتبہ نصیب ہوا۔ ۳۔ اس میں یہ ذکر نہیں کہ جو آدمی نماز کے دوران بولا تھا، سیدنا معاذ رضی اللہ عنہ نے اسے نماز لوٹانے کا کہا تھا یا نہیں کہا تھا۔ تو اس بارے میں گذارش ہے کہ وہ چونکہ اس سے آشنا نہ تھا، اس لیے اسے معذور جانا، اگر قصداً اور علم کے بعد ایسا کہا جاتا تو نماز فاسد ہو جاتی۔ (فتح الباری: ۸/۷۵)"}],[1568,"سیدنا ابو الدرداء رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کھڑے نماز پڑھ رہے تھے پس ہم نے سنا کہ آپ صلی اللہ علیہ وسلم فرما رہے ہیں: میں تیرے شر سے اللہ کی پناہ طلب کرتا ہوں۔ پھر تین بار فرمایا: میں تجھے اللہ کی لعنت کے ساتھ لعنت کرتا ہوں۔ اور آپ صلی اللہ علیہ وسلم نے اپنا ہاتھ بڑھایا، گویا آپ کسی چیز کو پکڑ رہے ہوں۔ جب آپ صلی اللہ علیہ وسلم نماز سے فارغ ہوئے تو ہم نے عرض کیا: یا رسول اللہ! ہم نے آپ کو نماز میں کچھ کلمات کہتے سنا ہے اور ہم نے اس سے پہلے آپ کو ایسا کہتے نہیں سنا۔ اور ہم نے یہ دیکھا کہ آپ صلی اللہ علیہ وسلم اپنے دونوں ہاتھ پھیلائے اور بڑھائے ہیں۔ فرمایا: اللہ کا دشمن ابلیس آگ کا شعلہ لے کر آیا تاکہ میرے چہرے پر لگائے تو میں نے تین بار کہا: میں تجھ سے اللہ کی پناہ طلب کرتا ہوں، پھر تین بار میں نے کہا: میں تجھے اللہ کی لعنت کے ساتھ لعنت کرتا ہوں تو وہ باز نہ آیا۔ پھر میں نے اس کو پکڑنے کا ارادہ کیا۔ قسم اللہ کی! اگر ہمارے بھائی سلیمان علیہ السلام کی دعا نہ ہوتی تو صبح کو وہ باندھا ہوتا اور مدینہ کے بچے اس سے کھیلتے۔‘‘","",{"k":"مسلم (542)۔ نسائی (1215)۔","e":"......۱۔ عفریت خبیث جن کو کہتے ہیں، جو سرکش ہو۔ ۲۔ اگر کوئی یہ کہے کہ یہ بات ثابت شدہ ہے کہ شیطان سیدنا عمر رضی اللہ عنہ کے سایہ سے بھاگ جاتا تھا۔ وہ نبی اکرم صلی اللہ علیہ وسلم پر کیسے حملہ آور ہو گیا۔ اس کا حل یہ ہے کہ سیدنا عمر رضی اللہ عنہ کے سامنے سے بھاگنا حقیقی طور پر بھاگنا نہیں بلکہ سیدنا عمر رضی اللہ عنہ کی ایمانی قوت کا بیان ہے۔ تو نبی اکرم صلی اللہ علیہ وسلم شیطان پر غالب آئے تھے اور اسے ہانک دیا تھا برتری آپ صلی اللہ علیہ وسلم ہی کو حاصل ہے۔ ۳۔ یہ بھی ثابت ہوا کہ قیدی کو ضرورت کے تحت مسجد میں باندھا جا سکتا ہے۔ ۴۔ یہ بھی ثابت ہوا کہ جن اجسام لطیفہ میں سے ہیں مگر انہیں انسان کے لیے دیکھنا ممکن ہے۔ ۵۔ ہواؤں اور جنوں کا مسخر ہونا حضرت سلیمان علیہ السلام کے ساتھ خاص تھا اور انہوں نے اس بادشاہی کی خصوصیت کی دعا کی تھی، نبی اکرم صلی اللہ علیہ وسلم کامل طور پر اس جن پر تصرف رکھنے کی قدرت رکھتے تھے۔ اس کے باوجود آپ صلی اللہ علیہ وسلم نے اسے گرفتار نہیں کیا تاکہ حضرت سلیمان علیہ السلام کا حق دعا محفوظ رہے۔ ۶۔ نبی اکرم صلی اللہ علیہ وسلم کا عفریت جن کو دھتکارنا، یہ دلیل ہے کہ اتنی حرکت کرنے سے نماز باطل نہیں ہوتی۔ ۷۔ اس سے اللہ تعالیٰ کی بارگاہ میں آپ صلی اللہ علیہ وسلم کی غایت درجہ کی حاجتمندی کی جھلک نمایاں ہوتی ہے۔ ۸۔ اس سے یہ بھی ثابت ہوا کہ دعا کے انداز پر نماز میں گفتگو کرنے سے نماز منقطع نہیں ہوتی۔"}],[1569,"سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بھول کر نماز میں کلام کیا اور پھر جو نماز پڑھ چکے تھے اسی پر بقیہ نماز پوری کی۔‘‘ (الاوسط)","",{"k":"طبرانی اوسط وفيه معلى بن مهدي، قال ابو حاتم يأتي احيانا با المناكير قال الذهبي، هو من العباد صدوق في نفسه، هيثمي: 2437."}],[1570,"سیدنا ابن مسعود رضی اللہ عنہ مرفوع بیان کرتے ہیں: ’’میرے پاس سے شیطان گذرا تو میں نے اس کو پکڑا اور اس کا گلہ دبایا یہاں تک کہ اس کی زبان کی ٹھنڈک میرے ہاتھ میں محسوس ہوئی۔ اور اس نے کہا: آپ صلی اللہ علیہ وسلم نے مجھے درد و الم پہنچایا۔‘‘ (احمد نے منقطع سند کے ساتھ روایت کیا)","",{"k":"احمد (3916)، بانقطاع، وابو عبيدة لم يسمع من ابيه، وبقية رجاله رجال الصحيح، هيثمي: 1594."}],[1571,"سیدنا معیقیب رضی اللہ عنہ سے روایت مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم سے سجدے کی جگہ مٹی کو برابر کرنے کا سوال کیا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: اگر تو ایسا کرنا چاہے تو ایک بار ہی کرنا۔","",{"k":"بخاری (1207)۔ مسلم (546)۔ ترمذی (380)۔ نسائی (1192)۔ ابوداؤد (946)۔ ابن ماجه (1026)۔ احمد (23098)۔ دارمی (1387)."}],[1572,"سیدنا ابو ذر رضی اللہ عنہ مرفوع بیان کرتے ہیں: ’’جب کوئی تم میں سے نماز کے لیے اُٹھے تو وہ کنکر کو ہاتھ نہ لگائے۔ رحمت الٰہی اس کے چہرے کے سامنے متوجہ ہوتی ہے۔‘‘ (اصحاب سنن)","",{"k":"ترمذی (379)، ضعیف البانی: 85، ابوداؤد (945)، ابن ماجه (1027)."}],[1573,"سیدنا ابو ذر رضی اللہ عنہ سے روایت ہے کہ کنکر چھونے ایک بار تو جائز ہیں اس فعل کا ترک کرنا سرخ اونٹوں کی دولت سے بھی زیادہ بہتر ہے۔","",{"k":"مؤطا (374)، موقوف علی ابی ذر.","e":"......۱۔ اس حدیث میں کنکریاں یا مٹی برابر کرنے کی ممانعت عام طور پر حالت کو مدنظر رکھتے ہوئے ہے، وگرنہ ریت یا تنکے وغیرہ ہوں تو ان کا حکم بھی یہی ہے۔ ۲۔ اس حدیث میں نماز میں کنکریوں وغیرہ کو چھونے کی کراہت بیان ہوئی ہے۔ ضرورت پڑے تو صرف ایک دفعہ ہاتھ لگایا جاسکتا ہے، زیادہ دفعہ جائز نہیں۔ ۳۔ نماز میں کنکریاں وغیرہ چھونے اور برابر کرنے کی ممانعت کی ایک وجہ تو یہ ہے کہ نماز سے توجہ کٹ جاتی ہے اور دوسری وجہ یہ ہے کہ اس طرح شغل خاطر سے رحمت الٰہی سے محرومی ہوتی ہے۔ سجدے میں اگر تکلیف ہو یا سخت ضرورت ہو تو ایک دفعہ درست کی جاسکتی ہیں۔ وگرنہ یہ عمل سخت مکروہ ہے۔"}],[1574,"سیدنا ابو ذر رضی اللہ عنہ سے مرفوع روایت ہے: اللہ تعالیٰ اپنے بندے کی طرف متوجہ رہتا ہے جب تک وہ ادھر اُدھر نہ دیکھے اور جب بندہ آس پاس دیکھنے لگے تو اللہ تعالیٰ اعراض کر دیتا ہے۔‘‘","",{"k":"نسائی (1195)، ضعیف، البانی: 57، ابوداؤد (909)، احمد (20997)، دارمی (1423)."}],[1575,"عائشہ رضی اللہ عنہا سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے نماز میں ادھر اُدھر دیکھنے کے بارے میں سوال کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: وہ مکاری کے ساتھ چھیننا ہے۔ شیطان بندے کی نماز میں سے کچھ حصہ چھینتا ہے۔‘‘ (اشیخین، نسائی)","",{"k":"بخاری (751)، ترمذی (590)، نسائی (1199)، ابوداؤد (910)، احمد (24225)."}],[1576,"سیدنا انس رضی اللہ عنہ مرفوع بیان کرتے ہیں: کچھ لوگوں کو کیا ہوا ہے جو نماز میں اپنی آنکھیں آسمان کی طرف اُٹھاتے ہیں۔ اس پر آپ صلی اللہ علیہ وسلم نے شدید بات کہی اور یہاں تک کہہ دیا کہ لوگ اس فعل کے ارتکاب سے باز رہیں یا پھر ان کی آنکھیں اُٹھائی جائیں گی۔","",{"k":"بخاری (750)۔ نسائی (1193)، ابوداؤد (913)، ابن ماجه (1044)، احمد (13299)، دارمی (1302)."}],[1577,"سیدنا انس رضی اللہ عنہ کو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اے بچے! تو اپنے آپ کو نماز کی حالت میں ادھر اُدھر دیکھنے سے بچا۔ نماز میں ادھر اُدھر دیکھنا ہلاکت ہے اور اگر ضروری ہو تو نوافل میں دیکھ فرائض میں نہ دیکھ۔‘‘","",{"k":"ترمذی (589)، ضعیف، البانی: 90."}],[1578,"سیدنا ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نماز میں دائیں اور بائیں نظر پھیرتے تھے اور گردن پیچھے کو نہیں پھیرتے تھے۔","",{"k":"ترمذی (587)، صحیح، البانی: 492، نسائی (1201)، احمد (2481)."}],[1579,"سیدنا معاذ بن انس رضی اللہ عنہ مرفوع بیان کرتے ہیں: ’’نماز میں ہنسنے والا، ادھر اُدھر دیکھنے والا اور انگلیاں چٹخانے والا یہ سب ایک جیسے ہیں۔‘‘ (احمد اور الکبیر سند کمزور ہے)","",{"k":"احمد (15194)، طبرانی کبیر وفيه ابن لهيعه وفيه كلام عن زبان بن فائد وهو ضعيف، هيثمي: 2424.","e":"......۱۔ التفات یہ ہوتا ہے کہ بغیر ضرورت سر کو دائیں یا بائیں موڑنا، نماز میں التفات تین طرح کا ہوتا ہے۔ (۱) چہرے کی ایک طرف بغیر ضرورت ہی دائیں یا بائیں پھیری جائے اور قبلے سے سینہ ادھر ادھر نہ ہو وہ قبلہ رخ ہی رہے۔ ایسا کرنا نماز میں مکروہ ہے۔ (۲) نماز میں التفات یہ ہے کہ آنکھ کی طرف سے مڑ کر دیکھا جائے، بہتر تو یہی ہے کہ یہ بھی نہ کیا جائے تاہم اس میں حرج نہیں نماز خراب نہیں ہوتی۔\n(۳) چہرہ اور سینہ ہی قبلہ سے پھیر لیا جائے، اس سے نماز باطل ہو جاتی ہے۔ ۲۔ اور جو یہ فرمایا ہے کہ نماز میں التفات سے شیطان کا جھپٹا ہے یہ وجہ ہے کہ اس طرح نماز کے التفات سے نمازی غفلت کا شکار ہوتا ہے۔ اور خشوع جاتا رہتا ہے جو کہ نماز کی اصل روح ہے تو شیطان اس التفات کو غنیمت تصور کرتا ہے اور ثواب سے محروم کر دیتا ہے۔ ۳۔ نماز میں اور اس دعا میں جو دورانِ نماز ہو رہی ہے، آنکھوں کو آسمان کی طرف اٹھانا منع ہے کیونکہ اس صورت میں انسان قبلہ سے ہٹ جاتا ہے اور نماز کی حالت سے خارج ہوتا ہے۔ اس لیے اس بارے میں سخت وعید ہے اور نماز کے دوران آنکھ آسمان کی طرف اٹھانا حرام قرار دیا گیا ہے، یہ اندھا کرنے کی سزا اس عمل کے حرام ہونے پر دلالت کرتی ہے۔ ۴۔ یہ بھی ثابت ہوا کہ نماز میں التفات سے جو اللہ تعالیٰ نے ثواب، رحمت، مغفرت، احسان اور عفو و درگزر کرنا ہوتا ہے یہ سلسلہ نماز میں ادھر ادھر دیکھنے سے منقطع ہو جاتا ہے لہذا اس سے احتراز کرنا چاہیے۔"}],[1580,"سیدنا جابر رضی اللہ عنہ مرفوع بیان کرتے ہیں: ’’دانت کھولنے اور مسکرانے سے نماز نہیں ٹوٹتی ہے۔ البتہ کھلکھلا کر ہنسنا نماز کو توڑ دیتا ہے۔‘‘ (الصغير)","",{"k":"طبرانی، صغیر، مرفوعاً وموقوفا ورجاله موثقون، هيثمي: 2440.","e":"......علامہ سید سابق رحمہ اللہ فرماتے ہیں، معمولی قسم کے ساتھ نماز میں کوئی فرق نہیں پڑتا۔ اگر زیادہ ہنسی آ جائے تو نماز باطل ہو جاتی ہے۔ ہنسی زیادہ کتنی ہوتی ہے اور کم کتنی ہوتی ہے۔ یہ اندازہ لگانا معروف بات ہے، اس کی حد بندی ممکن نہیں۔ (فقہ السنہ: ۱/۲۳۰)"}],[1581,"سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے نماز میں پہلو پر ہاتھ رکھنے کی ممانعت فرمائی ہے۔","",{"k":"بخاری (1219)، مسلم (545)، ترمذی (383)۔ نسائی (890)، ابوداؤد (947)، احمد (8930)، دارمی (1428)."}],[1582,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ وہ پہلو پر ہاتھ رکھنے پر انکار کرتی اور کہتی تھیں: یہود ایسا کرتے ہیں۔ (بخاری)","",{"k":"بخاری (3458)، مسلم (545)، ترمذی (383)۔ نسائی (890)، ابوداؤد (947)، احمد (8930)، دارمی (1428)."}],[1583,"سیدہ عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے نماز میں اور نماز کے بغیر بھی پہلو پر ہاتھ رکھنے کی ممانعت فرمائی ہے۔","",{"k":"رزین۔"}],[1584,"زیاد بن صبیح الحنفی کہتے ہیں کہ میں نے ابن عمر رضی اللہ عنہ کے پہلو میں نماز پڑھی، پس میں نے اپنا ہاتھ اپنے پہلو پر رکھا۔ جب وہ نماز سے فارغ ہوئے تو انہوں نے کہا: یہ نماز میں سختی کرنا یا صلیب بنانا ہے اور رسول اللہ صلی اللہ علیہ وسلم ایسا کرنے سے منع کرتے تھے۔","",{"k":"ابوداؤد (903)، صحیح، البانی: 798، نسائی (891)، احمد (5802)۔","e":"...... نماز میں اختصار یہ ہے کہ نمازی کوکھ پر ہاتھ رکھ لے۔ یہ احادیث نماز میں کوکھ پر ہاتھ رکھنے کے حرام ہونے پر دلالت کرتی ہیں۔ اس کے حرام ہونے کی وجہ ایک یہ ہے کہ یہودی نماز میں زیادہ تر یہ عمل اپناتے ہیں، ان کی مشابہت سے بچنے کے لیے کوکھ پر نماز میں ہاتھ رکھنے کی ممانعت وارد ہوئی ہے۔ دوسرے اقوال بھی ہیں، مثلاً یہ دوزخیوں کے آرام کا انداز ہوگا۔ دوسرا یہ ابلیس کی چال ہے۔ تیسرا یہ متکبروں کی سی چال ہے۔"}],[1585,"اسماعیل بن امیہ بیان کرتے ہیں کہ میں نے نافع رضی اللہ عنہ سے سوال کیا کہ جو شخص نماز میں ہاتھوں میں تشبیک کرے تو کیا حکم ہے؟ تو اس نے کہا: میں نے ابن عمر رضی اللہ عنہ سے سنا کہ انہوں نے کہا: یہ ان لوگوں کی نماز ہے جن پر غضب کیا گیا ہے۔ (ابوداؤد)","",{"k":"ابوداؤد (993)، صحیح، البانی: 876۔","e":"...... تشبیک (انگلیوں میں انگلیاں ڈالنا) اس کی ایک صورت یہ ہے کہ آدمی نے گھر سے وضو کیا ہے اور مسجد کی جانب روانہ ہوتا ہے یہ چونکہ نماز ہی میں شمار ہوتا ہے، یہ انگلیوں میں انگلیاں نہ ڈالے۔ دوسری صورت یہ ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے نماز ادا کر لی تھی جبکہ چار رکعات کی جگہ دو رکعات پڑھ لی تھیں، بھول گئے تھے تب آپ نے انگلیوں میں انگلیاں ڈالی تھیں۔ (بخاری مسلم) اس سے ثابت ہوا کہ نماز سے فارغ ہو کر یہ فعل جائز ہے اگر ضرورت ہو۔\nتیسری صورت یہ ہے جو ہماری زیر شرح حدیث میں آئی ہے کہ آدمی دوران نماز طاق رکعت یا جفت سے اوپر قیام کے لیے اٹھتے وقت کرتے ہیں، یہ منع ہے کیونکہ اسے سولی سے تشبیہ دی گئی ہے۔ اٹھتے وقت ہاتھوں پر اعتماد کرنا جائز ہے مگر یہ علیحدہ علیحدہ ہوں ایک دوسرے کے اندر نہ ملائے ہوں۔ ایک صورت پہلے گزر چکی ہے کہ رکوع میں دونوں گھٹنوں کے درمیان انگلیوں میں انگلیاں ڈال کر رکوع ہوا کرتا تھا، یہ منسوخ ہو چکا ہے ہتھیلیوں سے گھٹنوں کو پکڑنے کا حکم ہے۔"}],[1586,"سیدنا ابو ہریرہ رضی اللہ عنہ مرفوع بیان کرتے ہیں: نہ نماز میں دھوکا ہے اور نہ سلام کہنے میں دھوکا ہے۔‘‘ (ابوداؤد) امام احمد نے کہا: یعنی نہ تو سلام کہہ اور نہ تجھے سلام کہا جائے اور کسی شخص کو نماز میں مغالطہ اور دھوکا نہ دیا جائے یہاں تک کہ وہ نماز سے سلام پھیرے اور وہ شک میں ہو۔","",{"k":"ابوداؤد (928)، صحیح، البانی: 821۔","e":"...... غرار کا معنی ہے کہ اونٹنی نے دودھ کم کر دیا۔ ۱۔ اس حدیث کا ایک مطلب یہ ہے کہ سلام کہنے کا طریقہ بتایا گیا ہے کہ سلام کا جواب پورا دیا جائے، کم نہ کیا جائے۔ مثلاً ایک کہتا ہے، السلام علیکم ورحمۃ اللہ وبرکاتہ تو جواب بھی اتنا ہی کہے، کم نہ ہو۔ ۲۔ نماز میں نقصان کی ایک وجہ یہ ہے کہ رکوع و سجود پورا نہ کیا جائے۔ دوسری وجہ یہ ہے کہ نمازی کو شک گزرے کہ اس نے تین رکعات پڑھی ہیں یا چار پڑھی ہیں، اس میں اسے ایک صورت پر یقین بھی ہو مگر وہ چار کو زیادہ سمجھ کر چار تصور کر لیتا ہے اور شک میں رہتا ہے یہ بھی نقصان والی چیز ہے کیونکہ سنت طریقہ یہ ہے کہ شک پر توجہ نہ دی جائے، یقین پر بنیاد رکھیں۔ ۳۔ اس حدیث سے نماز میں سلام کا جواب نہ دینے پر بھی استدلال کیا جاتا ہے۔ لیکن استدلال اس سے درست نہیں۔ درست وہی ہے جو ہم نے اوپر وضاحت کی ہے۔ (عون المعبود: ۱/۳۴۸)"}],[1587,"سیدنا عثمان رضی اللہ عنہ سے حدیث مروی ہے کہ نبی صلی اللہ علیہ وسلم مسجد میں داخل ہوئے تو کچھ لوگوں کو دیکھا کہ وہ اپنے ہاتھ آسمان کی طرف اٹھا کر نماز پڑھ رہے ہیں پس آپ صلی اللہ علیہ وسلم نے اس پر سخت وعید فرمائی۔ (رزین)","",{"k":"رزین۔"}],[1588,"سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم مسجد قباء کی طرف تشریف لے گئے اور انصار رضی اللہ عنہم آکر آپ صلی اللہ علیہ وسلم کو سلام کہتے تھے جبکہ آپ نماز پڑھ رہے تھے۔ تو میں نے بلال رضی اللہ عنہ کو کہا: آنحضرت صلی اللہ علیہ وسلم کو تو نے کیا کرتے دیکھا، جب آپ صلی اللہ علیہ وسلم نماز پڑھ رہے تھے اور لوگ آ کر سلام کہتے تھے؟ انہوں نے کہا: آپ صلی اللہ علیہ وسلم ایسا کرتے تھے، پھر انہوں نے ہاتھ کھولا اور اندرونی حصہ نیچے کیا اور ہاتھ کی پشت اوپر کی طرف رکھی۔","",{"k":"ابوداؤد (927)، حسن، صحیح، البانی: 820، ترمذی (367)، نسائی (1187)، ابن ماجہ (1017)، دارمی (1361)۔","e":"...... علامہ شمس الحق رحمہ اللہ فرماتے ہیں: اس زیر شرح حدیث میں سلام کا جواب مکمل ہتھیلی کے اشارہ کے ساتھ دینے کا ذکر ہے۔ اور سیدنا جابر رضی اللہ عنہ والی حدیث میں پورے ہاتھ کے ساتھ نماز میں سلام کا جواب دینے کا آتا ہے۔ اور سیدنا صہیب رضی اللہ عنہ والی حدیث میں نماز میں سلام کا جواب انگلی سے دینے کا آتا ہے۔ اور سیدنا ابن مسعود رضی اللہ عنہ سے بیہقی میں سر کے ساتھ اشارہ سے نماز میں سلام کا جواب دینے کا آتا ہے۔ وَيُجْمَعُ بَيْنَ هَذِهِ الرِّوَايَاتِ بِأَنَّهُ صلى الله عليه وسلم فَعَلَ هَذَا مَرَّةً وَهَذَا مَرَّةً فَيَكُونُ جَمِيعُ ذَلِكَ جَائِزًا. (عون المعبود: ۱/۳۴۸) ’’ان تمام روایات میں مطابقت یوں ہوگی کہ نبی اکرم صلی اللہ علیہ وسلم نے سب طرح کیا ہے، ان تمام طریقوں سے نماز میں سلام کا جواب دینا جائز ہے۔‘‘"}],[1589,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے، وہ کہتی ہیں کہ میں ایک دن باہر سے آئی اور رسول اللہ صلی اللہ علیہ وسلم نماز پڑھ رہے تھے اور دروازہ بند تھا۔ میں نے دروازہ کھولنے کو کہا تو آپ صلی اللہ علیہ وسلم آگے بڑھے اور دروازہ کھول دیا اور پھر پشت کے بل پیچھے جا کر مصلیٰ پر گئے اور نماز مکمل کی۔","",{"k":"ابوداؤد (922)، حسن، البانی: 815، ترمذی (601)، نسائی (1206)۔"}],[1590,"نسائی کی روایت میں ہے میں نے دروازہ کھولنے کو کہا اور رسول اللہ صلی اللہ علیہ وسلم نفل نماز پڑھ رہے تھے اور دروازہ قبلہ کی جانب تھا۔","",{"k":"نسائی (1206)، حسن، البانی: 1151، ترمذی (601)، نسائی (1203)، ابوداؤد (922)۔","e":"...... ان دونوں احادیث سے ثابت ہوتا ہے کہ نفلی نماز ہو، فرض میں اس سے گریز کیا جائے کہ اگر دروازہ قبلہ رخ ہو ادھر ادھر نہ چلنا پڑے اور ضرورت کے تحت ہو بلا ضرورت نہ ہو۔ دوران نماز سیدھا چل کر مسافت تھوڑی ہو یا زیادہ ہو اور دروازے کھولنے کے بعد واپس لوٹنے سے نماز باطل نہیں ہوتی۔ یعنی دروازہ کھول کر جس جگہ نماز پڑھ رہا ہو اس جگہ پر واپس لوٹ جائے۔"}],[1591,"ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے ہر دو سیاہ رنگ کو نماز کی حالت میں مار دینے کا حکم دیا، سانپ اور بچھو کو۔","",{"k":"ابن ماجہ (1245)، صحیح، البانی: 1029، ترمذی (390)، نسائی (1203)، ابوداؤد (921)، احمد (9984)، دارمی (1504)۔","e":"...... سانپ یا بچھو اور جو چیز بھی ان کی مانند زہریلی ہو، اس حدیث میں اسے دورانِ نماز مارنے کا حکم دیا گیا ہے اگر چہ زیادہ چلنا پڑے۔ جو اس کے برعکس یہ نظریہ رکھتے ہیں کہ زیادہ حرکت سے زیادہ چلنے سے مارنا جائز نہیں یہ نظریہ ان دلائل کی بنیاد پر ہے کہ اس طرح عمل کثیر سے نماز سے توجہ ہٹ جاتی ہے اور ابوداؤد میں حدیث ہے کہ نماز میں سکون اختیار کرو۔ یہ عمل ان احادیث کے خلاف ہے۔ اس کے جواب میں علامہ عبید اللہ رحمانی رحمہ اللہ فرماتے ہیں: وَيُجَابُ عَنْ ذَلِكَ بِأَنَّ حَدِيثَ الْبَابِ خَاصٌّ فَلَا يُعَارِضُهُ مَا ذَكَرُوهُ. اس کا جواب یہ ہے کہ انہیں مارنے کے بارے میں جو حدیث آئی ہے۔ وہ خاص ہے، ان کے ذکر کردہ دلائل کے خلاف نہیں۔ یعنی نماز میں سکون ہی ہونا چاہیے مگر بچھو اور سانپ مارنے کا حکم اس کے خلاف نہیں۔ اس پر عمل کرنا ہے۔ علامہ صاحب رحمہ اللہ مزید فرماتے ہیں کہ درج ذیل واقعات بھی ہمارے اس موقف کی تائید کرتے ہیں۔ (۱) آپ صلی اللہ علیہ وسلم اپنی نواسی حضرت امامہ کو کبھی نماز میں اٹھاتے، کبھی نیچے رکھتے۔ (۲) منبر پر نماز پڑھائی اور سجدے کے لیے نیچے اترے۔ (۳) آپ صلی اللہ علیہ وسلم نے سامنے سے گزرنے والے کو ہاتھ سے روکنے کا حکم دیا ہے۔ یہ تمام واقعات دلالت کرتے ہیں کہ عمل کثیر سے بھی انہیں دوران نماز مارنا پڑے تو جائز ہے۔ (مرعاۃ: ۲/۲۰)"}],[1592,"سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے نماز میں کپڑا لٹکانے اور مرد کو منہ ڈھانپنے سے منع فرمایا ہے۔‘‘ (ترمذی وابوداؤد)","",{"k":"ابوداؤد (643)، حسن، البانی: 1151، ترمذی (378)، احمد (7875)، دارمی (1379)۔","e":"...... سدل، یہ ہے کہ کپڑے کو اتنا زیادہ لٹکانا کہ زمین کو لگ جائے۔ (۲) کپڑے کی دونوں جانب اکٹھی نہ کی ہوں اور کپڑا لٹکا دینا اگر دونوں جانب سمیٹ لی ہوں تو پھر سدل نہیں۔ (۳) اس کی ایک صورت یہ بھی بیان کی جاتی ہے کہ اپنے ہاتھ کپڑے میں داخل کیے ہوں اور کپڑا لپیٹا ہوا ہو، اسی حالت میں رکوع اور سجدہ کیا جائے۔ (۴) ایک قول سدل کے بارے میں یہ بھی ہے کہ تہبند کا درمیانہ حصہ سر پر رکھا جائے اور اس کے دونوں کنارے دائیں یا بائیں چھوڑ دیئے جائیں۔ بہر صورت یہ تمام صورتیں ایسی ہیں دوران نماز اس طرح کپڑا لٹکانا منع ہے۔ کیونکہ یہ یہودیوں کا طریقہ ہوا کرتا تھا، اس لیے اسے حرام قرار دیا گیا ہے۔ ۲۔ اس میں منہ لپیٹنے کی ممانعت آئی ہے، یہ ایک خاص طریقہ تھا، عرب کے لوگ پگڑیوں کے پلوؤں کے ساتھ نماز میں اپنے مونہوں پر نقاب سا بنا لیتے تھے، جس سے نماز میں مونہہ ڈھانپے جاتے تھے، ہاں اچانک کپڑا منہ کے سامنے آجائے تو پھر کوئی حرج نہیں۔ (عون المعبود: ۱/۲۴۵) نماز کے علاوہ ان دونوں صورتوں پر پابندی نہیں، یہ دوران نماز منع ہے۔"}],[1593,"بریدہ مرفوع بیان کرتے ہیں: تین کام گناہوں میں سے ہیں یہ کہ مرد کھڑا ہو کر پیشاب کرے اور یہ کہ نماز سے فارغ ہونے سے پہلے پیشانی صاف کرے اور یہ کہ سجدے کی جگہ میں پھونک مارے۔‘‘ (البزار، الاوسط)","",{"k":"بزار، طبرانی، اوسط، ورجاله البزار رجال الصحيح، هيثمي: 2454۔"}],[1594,"سیدہ ام سلمہ رضی اللہ عنہا سے روایت ہے کہ وہ کہتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے ہمارا ایک غلام دیکھا جس کو افلح کہتے تھے، جب وہ سجدہ کرتا تو پھونک مارتا تھا، پس آپ صلی اللہ علیہ وسلم نے فرمایا: اے افلح! اپنا چہرہ خاک آلود کر دے۔‘‘ (ترمذی)","",{"k":"ترمذی (381)، ضعیف، البانی: 59، احمد (26032)۔"}],[1595,"الازرق بن قیس سے روایت ہے کہ وہ کہتے ہیں ہم مقام اہواز میں خارجیوں سے لڑ رہے تھے پس اتفاقاً میں نہر کے کنارے پر گیا تو وہاں ایک شخص کھڑا نماز پڑھ رہا تھا اور اس کے گھوڑے کی لگام اس کے ہاتھ میں تھی۔ گھوڑے نے لگام کھینچنا شروع کر دی تو نمازی اس کے پیچھے چلنے لگا۔ ابوشعبہ نے کہا: وہ ابو برزہ اسلمی ہے۔ ایک خارجی شخص نے کہا: یا اللہ! اس بوڑھے کو ایسا ویسا کر دے۔ اس بوڑھے نے جب سلام پھیرا تو اس نے کہا: میں نے تیری بات سنی ہے اور میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چھ غزوات میں حصہ لیا ہے یا سات میں یا آٹھ میں اور میں نے آپ صلی اللہ علیہ وسلم کا آسانی کا وقت بھی دیکھا ہے یا آپ کا دین میں آسانی کرنا بھی دیکھا ہے، اور اگر میں اپنا چوپایا ساتھ لے کر واپس جاؤں تو یہ مجھے زیادہ پسند ہے بجائے اس کے کہ میں اس کو چھوڑ دوں اور وہ اپنی چراگاہ میں بھاگ جائے اور میرے لیے کام مشکل ہو جائے۔‘‘ (بخاری)","",{"k":"بخاری (1211)، احمد (19292)."}],[1596,"رزین کی روایت اس کے مثل ہے اور اس میں یہ بھی ہے: پس ابو برزہ رضی اللہ عنہ گھوڑے پر آئے اور نماز شروع کر دی اور گھوڑے کو چھوڑ دیا۔ گھوڑا چل پڑا تو اس نے نماز چھوڑ دی اور گھوڑے کے پیچھے چلے گئے اور بالآخر اس کو پہنچ کر پکڑا اور واپس آ کر اپنی نماز مکمل کی اور اس روایت میں یہ بھی ہے کہ اس نے کہا: میرا گھر دور ہے اور اگر میں نماز پڑھتا اور گھوڑے کو چھوڑ دیتا تو میں رات تک اپنے اہل وعیال میں نہ جا سکتا۔","",{"k":"رزین.","e":"...... جس نماز میں یہ جانور پکڑا تھا، وہ نماز عصر تھی۔\n۲۔ اس سے یہ بھی ثابت ہوا کہ جب بطور فخر نہ ہوں تو ضرورت کے تحت آدمی اپنے فضائل بیان کر سکتا ہے۔ ۳۔ اس سے یہ بھی ثابت ہوا کہ اگر اپنے سامان وغیرہ کے تلف اور ضائع ہونے کا خدشہ ہو تو اسے بچانے کے لیے نماز کاٹنا جائز ہے۔ ۴۔ یہ بھی ثابت ہوا کہ اس طرح قبلہ رخ جانور چلا جائے تو اسے پکڑ کر دوبارہ اپنی جائے نماز پر لوٹ کر نماز پڑھنا جائز ہے، اس سے نماز میں کوئی فرق نہیں آتا۔ (فتح الباری: ۳/۸۳)"}],[1597,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم رات کو نماز پڑھتے اور میں آپ صلی اللہ علیہ وسلم کے اور آپ کے قبلہ کے درمیان جنازے کی مثل لیٹی ہوتی تھی۔","",{"k":"مسلم (512)، بخاری (513)، نسائی (759)، ابوداؤد (714)، احمد (25649)، مؤطا (258)، دارمی (1413)."}],[1598,"اور ان کی روایات میں سے ہے: جب آپ صلی اللہ علیہ وسلم وتر پڑھنے کا ارادہ کرتے تو مجھے بیدار کر دیتے۔","",{"k":"بخاری (512)، نسائی (168)، ابوداؤد (714)، احمد (25356)، مؤطا (258)، دارمی (1413)."}],[1599,"’’عروہ بن زبیر سے روایت ہے اور ام المؤمنین سیدہ عائشہ رضی اللہ عنہا نے پوچھا: نماز کو کیا چیز توڑتی ہے؟ عروہ کہتے ہیں ہم نے کہا: عورت اور گدھا۔ تو ام المؤمنین نے کہا: پھر تو عورت بدترین جانور ہے۔ میں نے اپنا یہ حال دیکھا ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کے سامنے اس طرح لیٹی ہوتی جیسے جنازہ سامنے ہوتا ہے اور آپ صلی اللہ علیہ وسلم نماز پڑھ رہے ہوتے تھے۔","",{"k":"مسلم (512)، بخاری (513)، نسائی (759)، ابوداؤد (714)، احمد (25649)، مؤطا (258)، دارمی (1413)."}],[1600,"ام المؤمنین رضی اللہ عنہا کے سامنے یہ مذاکرہ کیا گیا کہ نماز کو کون سی چیز توڑتی ہے؟ پس کتے، گدھے اور عورت کو بیان کیا گیا۔ ام المؤمنین نے کہا: یقیناً تم نے ہم خواتین کو گدھوں اور کتوں کے برابر قرار دے دیا ہے۔ قسم اللہ کی! میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس حال میں نماز پڑھتے دیکھا ہے کہ آپ صلی اللہ علیہ وسلم نماز پڑھ رہے ہیں اور میں چار پائی پر آپ صلی اللہ علیہ وسلم کے قبلہ کے درمیان لیٹی ہوں، مجھے اُٹھنے کی ضرورت پیش آتی تو میں سیدھا اُٹھ کر بیٹھنا اس لیے ناپسند کرتی تھی کہ مجھ سے رسول اللہ صلی اللہ علیہ وسلم کو تکلیف نہ ہو، پس میں آپ صلی اللہ علیہ وسلم کے پاؤں کی طرف سے پھسل کر اُتر جاتی تھی۔","",{"k":"مسلم (512)، بخاری (514)، نسائی (759)، ابوداؤد (714)، احمد (25649)، مؤطا (258)، دارمی (1413)."}],[1601,"سیدہ عائشہ رضی اللہ عنہا کہتی ہیں میں رسول اللہ صلی اللہ علیہ وسلم کے سامنے سویا کرتی تھی اور میرے پاؤں آپ صلی اللہ علیہ وسلم کے قبلہ کی طرف ہوا کرتے تھے۔ آپ صلی اللہ علیہ وسلم سجدہ کرنے لگتے تو مجھے ٹھونکتے اور میں پاؤں سکیڑ دیتی اور جب آپ صلی اللہ علیہ وسلم کھڑے ہو جاتے تو میں پاؤں پھیلا دیتی تھی اور ان ایام میں گھروں میں چراغ نہیں ہوا کرتے تھے۔","",{"k":"بخاری (382)، نسائی (759)، ابوداؤد (714)، احمد (25649)، مؤطا (258)، دارمی (1413)."}],[1602,"سیدہ عائشہ رضی اللہ عنہا مرفوع بیان کرتی ہیں: مسلمان کی نماز کو کوئی چیز نہیں توڑتی مگر گدھا، کافر، کتا اور عورت۔ عائشہ رضی اللہ عنہا نے کہا: رسول اللہ صلی اللہ علیہ وسلم ہم خواتین حقیر حیوانوں کے ساتھ ملا دی گئی ہیں۔","",{"k":"احمد (24025)، ورجاله موثقون، هيثمي: 2291."}],[1603,"سیدنا ابو ذر رضی اللہ عنہ مرفوع بیان کرتے ہیں: ’’جب تم میں سے کوئی شخص کھڑا نماز پڑھ رہا ہو تو اس کے سامنے کجاوے کی پچھلی لکڑی کے برابر کوئی چیز موجود ہو تو وہی اس کا سترہ بن کر پردہ بن جائے گی۔ اور اگر اس کے سامنے کجاوے کی پچھلی لکڑی کے برابر کوئی چیز ہو تو اس کی نماز کو گدھا، عورت اور سیاہ کتا توڑتا ہے۔ راوی کہتا ہے میں نے کہا: اے ابو ذر! سیاہ کتے کا سرخ کتے اور زرد گتے سے امتیاز کیا ہے؟ انہوں نے کہا: اے میرے بھائی کے بیٹے! میں نے بھی رسول اللہ صلی اللہ علیہ وسلم سے اسی طرح سوال کیا تھا جیسے تو نے مجھ سے سوال کیا ہے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’سیاہ کتا شیطان ہے۔‘‘ (مسلم اور اصحاب سنن)","",{"k":"مسلم (510)، ترمذی (338)، نسائی (750)، ابوداؤد (702)، ابن ماجہ (3210)، احمد (20920)، دارمی (1414)."}],[1604,"سیدنا فضل بن عباس رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے غیر آباد علاقے میں ہماری ملاقات کی، ہماری ایک کتیا اور ایک گدھی تھی پس آپ صلی اللہ علیہ وسلم نے نماز عصر پڑھی اور وہ دونوں جاندار آپ کے سامنے تھے، نہ تو آپ صلی اللہ علیہ وسلم نے ان کو ڈانٹ کر دور کیا اور نہ ان کو پیچھے ہٹایا۔","",{"k":"نسائی (753)، منکر، البانی: 30، ابوداؤد (718)."}],[1605,"کثیر بن کثیر بن مطلب بن ابی وداعہ اپنے گھر کے بعض افراد سے روایت کرتے ہیں اور وہ اس کے دادا سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم کو باب بنو سہم کے قریب دیکھا، لوگ آپ صلی اللہ علیہ وسلم کے سامنے گذرتے تھے اور آپ صلی اللہ علیہ وسلم کے اور کعبہ کے درمیان سترہ بھی نہیں تھا۔","",{"k":"ابوداؤد (2016)، ضعیف، البانی: 437، نسائی (2959)، ابن ماجہ (2958)، احمد (26699)."}],[1606,"میں کہتا ہوں: القزوینی نے نہایت عمدہ طریقے سے سند واضح کی ہے اور کہا ہے: کثیر بن کثیر بن مطلب بن ابی وداعہ اسلمی نے روایت کی اپنے باپ سے وہ روایت کرتے ہیں مطلب سے، انہوں نے کہا میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا۔ (آگے مثل حدیث سابق ہے)","",{"k":"ابن ماجہ (2958)، ضعیف: 642، نسائی (758)، نسائی (758)، ابوداؤد (2016)، احمد (26699)."}],[1607,"سیدنا ابو سعید رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’نماز کو کوئی چیز نہیں توڑتی اور تم سے جہاں تک روکا جائے اس کو منع کرو وہ شیطان ہے۔‘‘","",{"k":"ابوداؤد (719)، ضعیف، البانی: 143، بخاری (3275)، مسلم (505)، نسائی (4862)، ابن ماجہ (954)، احمد (11477)، مؤطا (364)، دارمی (1411)."}],[1608,"ابو صالح السمان نے کہا: میں نے ابو سعید خدری رضی اللہ عنہ کو جمعہ کے دن ایک چیز کو سترہ بنا کر اس کی طرف نماز پڑھتے دیکھا۔ ایک جوان نے جو بنو ابی معیط میں سے تھا اس کے سامنے سے گذرنے کا ارادہ کیا تو ابو سعید نے اس کے سینے پر مار کر روکا۔ جوان نے دیکھا تو وہ دو مرتبہ گذرنے کے لیے لوٹ آیا، پس ابو سعید نے پہلے سے زیادہ زور سے روکا تو اس نے ابو سعید سے بد کلامی کی اور مروان حاکم مدینہ کے پاس جا کر ابو سعید رضی اللہ عنہ کی رکاوٹ وغیرہ کی شکایت کی۔ اس کے پیچھے ابو سعید رضی اللہ عنہ بھی مروان کے پاس پہنچ گئے۔ مروان نے کہا: اے ابو سعید! تیرے ساتھ تیرے بھائی کے بیٹے کا کیا معاملہ ہے؟ ابو سعید رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے: ’’جب تم میں سے کوئی شخص لوگوں کے درمیان سترہ رکھ کر نماز پڑھتا ہو اور کوئی آدمی اس نمازی کے سامنے سے گذرنے کا ارادہ کرے تو اس کو روک دے، اگر وہ باز نہ آئے تو اس سے لڑائی کرو وہ شیطان ہے۔‘‘","",{"k":"بخاری (509)، مسلم (505)، نسائی (4862)، ابوداؤد (700)، ابن ماجہ (954)، احمد (11477)، مؤطا (364)، دارمی (1411)."}],[1609,"سیدنا ابو سعید خدری رضی اللہ عنہ فرماتے ہیں کہ وہ نماز پڑھ رہے تھے اور مروان کے بیٹے نے سامنے سے گذرنے کا ارادہ کیا تو اس نے روک دیا، تو وہ باز نہ آیا پس ابو سعید رضی اللہ عنہ نے مارا۔ تو لڑکا روتا چلا گیا یہاں تک کہ مروان کے پاس پہنچ گیا اور اس کو خبر دی۔ مروان نے ابو سعید رضی اللہ عنہ کو کہا: تو نے اپنے بھائی کے بیٹے کو کیوں مارا ہے؟ انہوں نے کہا: میں نے اس کو نہیں مارا البتہ شیطان کو مارا ہے۔ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے۔ ...... مثل حدیث سابق۔","",{"k":"نسائی (4862)، صحیح، البانی: 4518، بخاری (3275)، مسلم (505)، ابوداؤد (700)، ابن ماجہ (954)، احمد (11213)، مؤطا (364)، دارمی (1411)."}],[1610,"امام مالک رحمہ اللہ کو یہ خبر پہنچی ہے کہ سعد بن ابی وقاص رضی اللہ عنہ صفوں کے سامنے سے جبکہ نماز پڑھی جا رہی ہوتی تھی گذرتے تھے۔","",{"k":"مؤطا."}],[1611,"سیدنا انس رضی اللہ عنہ حدیث مرفوع بیان کرتے ہیں: ’’امام کا سترہ اس کی اقتداء کرنے والوں کے لیے بھی سترہ ہے۔‘‘ (الاوسط، سند ضعیف ہے)","",{"k":"طبرانی اوسط، وفیه سوید بن عبدالعزیز وهو ضعیف، هيثمي: 2306."}],[1612,"ابو جہیم رضی اللہ عنہ مرفوع بیان کرتے ہیں: ’’اگر نمازی کے سامنے سے گذرنے والے کو معلوم ہو کہ اس پر کتنا گناہ لازم آتا ہے تو وہ اگر چالیس تک بھی انتظار کرے تو بہتر ہے اس سے کہ نمازی کے سامنے سے گذرے۔‘‘ راوی ابو النصر نے کہا: میں نہیں جانتا چالیس دن یا چالیس مہینے یا چالیس سال مراد ہیں۔","",{"k":"بخاری (510)، مسلم (507)، ترمذی (336)، نسائی (756)، ابوداؤد (701)، ابن ماجہ (945)، احمد (17089)، مؤطا (365)، دارمی (1417)."}],[1613,"نبی کریم صلی اللہ علیہ وسلم سے روایت کی گئی ہے: ’’اگر تم میں سے کوئی سو سال کھڑا رہے۔‘‘","",{"k":"ترمذی (336)، صحیح، البانی: 276، بخاری (510)، مسلم (507)، نسائی (756)، ابوداؤد (701)، ابن ماجہ (945)، احمد (17079)، دارمی (1417)."}],[1614,"عطاء بن یسار سے روایت ہے کہ وہ کعب الاحبار سے موقوف روایت نقل کرتے ہیں: ’’اگر وہ زمین میں دھنس جائے تو یہ اس کے لیے بہتر ہے۔‘‘ (الحدیث)","",{"k":"مؤطا (366)."}],[1615,"یزید بن نمران سے روایت ہے کہ انہوں نے ایک مرد تبوک میں دیکھا وہ بیٹھا ہی رہتا تھا۔ تو اس نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نماز پڑھ رہے تھے اور وہ شخص گدھے پر سوار آپ صلی اللہ علیہ وسلم کے سامنے سے گذرا تو آپ صلی اللہ علیہ وسلم نے فرمایا: یا اللہ! اس کے نشانات قدم مٹا دے۔ وہ کہتا ہے اس کے بعد وہ اپنے قدموں پر کبھی نہیں چل سکا۔‘‘","",{"k":"ابوداؤد (705)، ضعیف، البانی: 138، احمد (22686)."}],[1616,"ایک روایت میں ہے: ’’اس نے ہماری نماز توڑی دی ہے اللہ اس کے نشانِ قدم مٹا دے۔‘‘ (ابو داؤد)","",{"k":"ابوداؤد (707)، ضعیف، البانی: 140، احمد (22686)."}],[1617,"ابو صہباء سے روایت ہے کہ ہم نے ابن عباس رضی اللہ عنہما کے نزدیک ذکر کیا ان چیزوں کا جو نماز کو توڑتی ہیں تو ابن عباس رضی اللہ عنہما نے کہا: میں اور بنو عبد المطلب کا لڑکا گدھے پر سوار ہو کر آئے اور رسول اللہ صلی اللہ علیہ وسلم نماز پڑھا رہے تھے۔ پس وہ لڑکا اُترا اور میں بھی اُتر گیا اور ہم نے گدھے کو صف کے آگے چھوڑ دیا۔ پس آپ صلی اللہ علیہ وسلم نے کوئی پروا نہ کی۔","",{"k":"ابوداؤد (716)، صحیح، البانی: 660، بخاری (4412)، مسلم (504)، ترمذی (337)، نسائی (754)، ابن ماجہ (947)، احمد (3444)، مؤطا (369)، دارمی (1415)."}],[1618,"ابوداؤد نے اپنے الفاظ میں یہ زائد بیان کیا ہے: اور دو لڑکیاں آئیں وہ بنو عبد المطلب میں سے تھیں تو وہ صف کے درمیان آ داخل ہوئیں، پس آپ صلی اللہ علیہ وسلم نے اس کی کوئی پروا نہیں کی۔","",{"k":"ابوداؤد (716)، صحیح، البانی: 660، بخاری (4412)، مسلم (504)، ترمذی (337)، نسائی (754)، ابن ماجہ (947)، احمد (3444)، مؤطا (369)، دارمی (1415)."}],[1619,"سیدنا ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کوئی شخص سترے کے بغیر نماز پڑھتا ہے تو اس کی نماز کو گدھا، خنزیر، یہودی، مجوسی اور عورت توڑ دیتی ہے۔ اور کنکر مارنے کے فاصلے برابر یہ مذکورہ اشیاء گذریں تو اس کی نماز جائز ہو جاتی ہے۔‘‘","",{"k":"ابوداؤد (704)، ضعیف، البانی: 137، نسائی (751)، ابن ماجہ (749)، احمد (3231)."}],[1620,"اور ایک مرفوع روایت میں ہے: ’’حائضہ عورت اور کتا نماز کو توڑتا ہے۔‘‘","",{"k":"ابوداؤد (704)، ضعیف، البانی: 137، نسائی (751)، ابن ماجہ (749)، احمد (3231)."}],[1621,"اور ایک روایت میں ہے کہ سوئے ہوئے آدمی کے پیچھے حلقے میں بیٹھے لوگوں کے پیچھے اور گفتگو کرنے والوں کے پیچھے نماز نہ پڑھا کرو۔","",{"k":"ابوداؤد (709)، حسن، البانی: 642، ابن ماجہ (959)."}],[1622,"سیدنا ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نماز پڑھ رہے تھے اور بکری کا بچہ آپ صلی اللہ علیہ وسلم کے سامنے سے گذرنے لگا تو آپ اس سے بچاؤ کرنے لگے۔","",{"k":"ابوداؤد (709)، صحیح، البانی: 653، ابن ماجہ (953)، احمد (3183)."}],[1623,"عمرو بن شعیب رضی اللہ عنہ سے روایت ہے وہ اپنے باپ سے اور وہ اس کے دادا سے روایت بیان کرتے ہیں کہ بکری کا بچہ آیا اور آپ کے سامنے سے گذرنے لگا تو آپ صلی اللہ علیہ وسلم اس سے آگے بڑھتے گئے یہاں تک کہ اپنا بطن مبارک دیوار سے لگا دیا اور بکری کا بچہ آپ صلی اللہ علیہ وسلم کی پشت کے پیچھے سے گذرا۔‘‘","",{"k":"ابوداؤد (708)، حسن، صحیح 652، احمد (6813).","e":"...... ان احادیث سے ثابت ہوا۔ ۱۔ کھلی فضا میں سترہ کی تاکید ہے اور سفر میں بھی اسے اختیار کیا جائے۔ اور جو چیز بھی نمازی اپنے سامنے گاڑے وہ سترہ بن جاتی ہے۔ اور ہتھیار لے کر امام وقت کی حفاظت کے لیے ساتھ چلنا جائز ہے، یہ اس وقت منع ہے جب ہتھیار اٹھانے سے نمازیوں کو تکلیف ہو۔ ۲۔ حیوان کو بطور سترہ سامنے بٹھا کر نماز پڑھنا جائز ہے اور اونٹ کے قریب نماز پڑھنے کا جواز بھی ثابت ہوا ہے اور جو منع آیا ہے کہ اونٹ کے باڑے میں نماز نہ پڑھی جائے وہ باڑے کے اندر ہے اسے بطور سترہ رکھ کر نماز پڑھنا جائز ہے۔ علامہ عبید اللہ رحمانی رحمہ اللہ فرماتے ہیں کہ امام شافعی رحمہ اللہ جانور اور عورت کو سترہ بنانے کے قائل نہیں، ان کا مذہب تو ہمیشہ اتباع حدیث رہا ہے، شاید انہیں یہ حدیث نہ پہنچی ہو۔ (مرعاۃ: ۲/۲۲۰) ۳۔ نمازی، فرض، نفل، سنت پڑھ رہا ہو، یا امام ہو یا منفرد ہو اس کے آگے سے گزرنا بہت بڑا گناہ ہے جسے کبیرہ کہتے ہیں۔ ۴۔ نمازی کے آگے سے گزرنے سے چونکہ صرف گزرنے والا ہی کبیرہ گناہ نہیں کرتا، نمازی کی نماز میں بھی نقص پیدا ہوتا ہے اس لیے گزرنے والے کو شیطان قرار دیا گیا ہے کیونکہ ایسی قبیح حرکت پر شیطان ہی آمادہ کرتا ہے۔ اس لیے نمازی کو حکم ہے وہ اسے روکے اگر باز نہ آئے تو اسے سختی سے روکے خواہ شدید انداز ہی اپنانا پڑے تاکہ دونوں نقصان سے محفوظ رہیں۔ نمازی نماز کے نقصان سے اور گزرنے والا گناہ اٹھانے سے محفوظ رہے۔ ۵۔ ایک رائے تو صحابہ کرام رضی اللہ عنہم سے لے کر عام علمائے کرام کی یہی ہے کہ نمازی نے سترہ نہ رکھا ہو تو اس کے آگے سے حائضہ عورت اور کتا اور گدھا گزرے تو نماز ٹوٹ جاتی ہے۔ دوسری رائے یہ ہے کہ اس صورت میں نماز ٹوٹنے کی روایات صحیح ہیں، مگر یہ منسوخ ہو چکی ہیں۔ اس کو منسوخ کرنے والی وہ روایت ہے، جس میں آیا ہے کہ نماز کو کوئی چیز نہیں کاٹتی۔ (ابوداؤد) ابن حزم رحمہ اللہ اس روایت کو ضعیف قرار دیتے ہیں، مگر علامہ عبید اللہ رحمہ اللہ فرماتے ہیں، ان کا اسے ضعیف قرار دینا قابل قبول نہیں۔ (مرعاۃ: ۲/۲۳۷) ابن حزم کا خیال یہی ہے کہ نمازی کے آگے سے سیاہ کتے، حائضہ کے گزرنے اور گدھے کے گزرنے سے نماز ٹوٹ جاتی ہے۔ (محلی: ۳/۱۴) صحیح ترین بات یہ ہے کہ علامہ احمد شاکر رحمہ اللہ فرماتے ہیں: وَالصَّحِيحُ الَّذِي أَرْضَاهُ وَاخْتَارُهُ أَنَّ أَحَادِيثَ الْقَطْعِ مَنْسُوخَةٌ بِحَدِيثِ لَا يَقْطَعُ الصَّلَاةَ شَيْءٌ.\n(۲/۱۶۴ تعلیق علی الترمذی) ’’صحیح بات یہی ہے جسے میں پسند کرتا ہوں اور اختیار کرتا ہوں کہ وہ احادیث جن میں نمازی کے آگے سے گزرنے سے نماز کے کٹ جانے کا آتا ہے وہ منسوخ ہیں اور اس حدیث نے انہیں منسوخ قرار دیا ہے جس میں آتا ہے کہ نماز کو کوئی چیز نہیں توڑتی۔‘‘ ۶۔ بیوی سامنے لیٹی ہو تو نماز درست رہتی ہے ٹوٹتی نہیں اور سامنے بیٹھنے والا اگر ایک طرف سے ہو کر گزر جائے تو نمازی کی نماز میں فرق نہیں آتا۔ ۷۔ امام کا سترہ سب کے لیے سترہ ہے، امام کے آگے سترہ ہو اور مقتدیوں کے آگے سے کوئی گزر جائے تو نہ گزرنے والے کو گناہ ہوتا ہے اور نہ نمازیوں کی نماز میں کمی آتی ہے۔"}],[1624,"سیدنا ابو ہریرہ رضی اللہ عنہ مرفوع حدیث بیان کرتے ہیں: ’’جب تم میں سے کوئی شخص نماز پڑھے تو اپنے چہرے کے سامنے کوئی چیز رکھ دے۔ اگر دوسری کوئی چیز نہ ہو تو اپنا عصا ہی رکھے اور اگر یہ بھی نہ ہو تو خط کھینچ دے اور پھر اس کے سامنے سے کوئی چیز گذر جائے تو کوئی حرج نہ ہوگا۔ (ابو داؤد) بعض نے کہا: خط طول میں ہو اور بعض نے کہا: عرض میں ہلالی شکل بنائے۔‘‘","",{"k":"ابوداؤد (689)، ضعیف، البانی: 134، احمد (6813)."}],[1625,"موسی بن طلحہ اپنے باپ طلحہ بن عبید اللہ رضی اللہ عنہ سے مرفوع حدیث بیان کرتے ہیں: ’’جب تم میں سے کوئی شخص کجاوے کے پچھلے حصے کی لکڑی برابر اپنے سامنے رکھ دے تو پھر وہ نماز پڑھے اور کوئی پروا نہ کرے کہ اس لکڑی کے پیچھے سے کون گذرا ہے۔‘‘","",{"k":"مسلم (499)، ترمذی (335)، ابوداؤد (685)، ابن ماجہ (940)، احمد (1396)."}],[1626,"عبدالملک بن ربیع سے روایت وہ اپنے باپ سے اور وہ اس کے دادا سبرہ بن معبد رضی اللہ عنہ سے مرفوع حدیث بیان کرتے ہیں: ’’مرد اپنی نماز کے لیے تیر کو سترہ بنائے اور جب تم میں سے کوئی شخص نماز پڑھنے لگے تو مناسب ہے کہ تیر سے سترہ بنالے۔‘‘ (احمد، الموصلی، الکبیر)","",{"k":"احمد (1418)، موصلی، طبرانی کبیر ورجاله رجال الصحیح، هيثمي: 2277."}],[1627,"سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم جب عید کے دن نکلتے تو آپ برچھی رکھنے کا حکم دیتے اور وہ آپ کے سامنے رکھی جاتی اور اس کی طرف آپ صلی اللہ علیہ وسلم نماز پڑھتے۔ اور لوگ آپ صلی اللہ علیہ وسلم کے پیچھے کھڑے ہوتے اور آپ سفر میں بھی ایسا ہی کرتے تھے۔ اسی وجہ سے امراء وخلفاء نے یہ چیز اختیار کی ہے۔","",{"k":"بخاری (494)، مسلم (501)، ابوداؤد (687)، ابن ماجه (1305)، احمد (6383)."}],[1628,"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے: کہ رسول اللہ صلی اللہ علیہ وسلم اپنی سواری کو سامنے عرضاً بٹھا دیتے اور اس کی طرف نماز پڑھتے۔","",{"k":"بخاری (507)، مسلم (502)، ترمذی (352)، ابوداؤد (692)، احمد (6093)."}],[1629,"ضباعہ بنت مقداد اپنے باپ مقداد بن اسود رضی اللہ عنہ سے روایت کرتے ہیں کہ میں نے نہیں دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم نے لکڑی، ستون یا درخت کی طرف نماز پڑھی ہو مگر ان اشیاء کو آپ صلی اللہ علیہ وسلم کی دائیں یا بائیں طرف کو رکھ کر ہی نماز پڑھا کرتے تھے اور پوری طرح سامنے نہ رکھتے تھے۔","",{"k":"ابوداؤد (693)، ضعيف: 136، احمد (23308)."}],[1630,"سہل بن ابی حثمہ رضی اللہ عنہ مرفوع حدیث کرتے ہیں: ’’جب تم میں سے کوئی شخص سترے کی طرف نماز پڑھے تو اس کے قریب کھڑا ہوتا کہ شیطان اس کی نماز قطع نہ کرا دے۔‘‘","",{"k":"ابوداؤد (695)، صحيح، البانی: 643، نسائی (748).","e":"...... ۱۔ ایک نیزہ وہ تھا جس کے ساتھ سیدنا زبیر بن عوام رضی اللہ عنہ نے مشرکوں کا ایک آدمی قتل کیا تھا اور اس سے یہ نیزہ چھینا تھا۔ نبی اکرم صلی اللہ علیہ وسلم نے سیدنا زبیر رضی اللہ عنہ سے وہ نیزہ لے لیا تھا، جب نماز پڑھتے تو اسے آگے گاڑ لیتے تھے۔ ایک نیزہ وہ تھا جو سیدنا نجاشی رضی اللہ عنہ نے آپ صلی اللہ علیہ وسلم کو ہدیہ میں دیا تھا۔ اسے آپ لے کر عید کے دن جاتے تھے۔\nتھے۔ اور عید گاہ میں گاڑ لیتے تھے۔ نجاشی والا نیزہ ملنے سے پہلے آپ صلی اللہ علیہ وسلم حضرت زبیر والا نیزہ ہی رکھتے تھے۔ بعد میں نجاشی والا نیزہ رکھا۔ (فتح الباری: ۱/۵۷۳) ۲۔ دوسرے سے خدمت لینا جائز ہے۔ ۳۔ نماز کے لیے یا سفر میں دشمن سے دفاع کے لیے آلہ رکھنا مسنون ہے۔ اور یہ بھی ثابت ہوا کہ تیر جتنی باریک چیز ہو تو سترہ بن سکتی ہے اور کجاوے کی لکڑی جتنی بلند چیز جو کہ تقریباً چھ انچ ہوتی ہے کو بطور سترہ رکھا جا سکتا ہے۔ اور جب سترہ رکھ لیں تو اس کے ماوراء گزرنے سے نمازی کا اور گزرنے والے کا کوئی نقصان نہیں ہوتا۔ اور یہ بھی ثابت ہوا کہ سواری کو سترہ بنا کر نماز پڑھنا جائز ہے۔ ۴۔ سترہ کے قریب تر ہو کر نماز پڑھی جائے، تقریباً تین ہاتھ کا اندازہ رکھا جائے تاکہ سجدہ ہو سکے۔ ۵۔ شیطان کا غلبہ روکنے میں اور وسوسہ ڈالنے میں سترہ بڑی رکاوٹ ہے اور سترہ رکھنے سے خشوع وخضوع قائم رکھنے میں تعاون حاصل ہوتا ہے۔"}],[1631,"سیدنا ابو قتادہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نماز پڑھتے اور آپ صلی اللہ علیہ وسلم نے امامہ بنت زینب کو اٹھایا ہوتا تھا، وہ رسول اللہ صلی اللہ علیہ وسلم کی بیٹی زینب اور ابو العاص رضی اللہ عنہ کی بیٹی ہے۔ جب آپ سجدہ کرتے تو اس کو زمین پر رکھ دیتے اور جب کھڑے ہوتے تو اُٹھا لیتے۔","",{"k":"بخاری (516)، مسلم (543)، نسائی (1205)، ابوداؤد (920)، احمد (22145)."}],[1632,"سیدنا ابو قتادہ رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ صلی اللہ علیہ وسلم لوگوں کو نماز پڑھا رہے تھے اور امامہ بنت ابی العاص رضی اللہ عنہا آپ کے کاندھے پر تھی، آپ صلی اللہ علیہ وسلم رکوع جاتے تو اس کو زمین پر رکھ دیتے اور جب سجدے سے اُٹھتے تو اس کو لوٹا کر کندھے پر بٹھا دیتے۔","",{"k":"مسلم (543)، نسائی (1205)، ابوداؤد (920)، احمد (22145)، مؤطا (412)، دارمی (1359).","e":"...... ۱۔ امامہ رضی اللہ عنہا اپنی نواسی کو اٹھانا، پھر نیچے رکھنا یہ فعل نبی اکرم صلی اللہ علیہ وسلم سے سرزد ہوتا تھا، بچی ایسا نہ کرتی تھی کہ کبھی بیٹھ جائے اور کبھی نیچے اتر جائے۔\n۲۔ اس حدیث میں یہ دلالت بھی ہے کہ ایک آدمی بچے کو یا کسی پاک حیوان کو دورانِ نماز اٹھاتا ہے تو اس کی نماز درست ہے۔ اور یہ بھی ثابت ہوا کہ بچوں کے لباس اور جسم پاک ہیں تاوقتیکہ کوئی ظاہر نجاست نظر نہ آئے۔ اور یہ بھی پتہ چلا کہ نماز میں ایک حرکت جب پے در پے نہ ہو تو اس سے نماز میں فرق نہیں آتا۔ ۳۔ اس میں نبی اکرم صلی اللہ علیہ وسلم کے بچوں سے پیار اور کمزوروں سے لطف ورحمت کی جھلک بھی نمایاں ہوتی ہے۔ ۴۔ یہ بھی ثابت ہوتا ہے کہ بچوں کو مسجدوں میں لے جانا جائز ہے۔ ۵۔ یہ بھی ثابت ہوا کہ فرض نماز ہو، یا نفل ہو، امام ہو یا اکیلا ہو، نماز میں بچے کو اٹھانا یا رکھنا جائز ہے۔ ۶۔ بعض لوگ اس طرح بچے کو نماز میں اٹھانے کو جائز قرار نہیں دیتے۔ اور اس پر دلیل بھی پیش کرتے ہیں، ان کے بارے میں علامہ عبید اللہ رحمانی رحمہ اللہ فرماتے ہیں:\nوَكُلُّ هَذِهِ الدَّعَاوِي بَاطِلَةٌ مَرْدُودَةٌ فَإِنَّهُ لَا دَلِيلَ عَلَيْهَا وَلَا ضَرُورَةَ إِلَيْهَا، بَلِ الْحَدِيثُ صَحِيحٌ صَرِيحٌ فِي جَوَازِ ذَلِكَ وَلَيْسَ فِيهِ مَا يُخَالِفُ قَوَاعِدَ الشَّرْعِ. (مرعاة: ۲/۸)\n’’یہ تمام دعوا جات باطل اور مردود ہیں ان پر کوئی دلیل نہیں، نہ ہی ان دعاوی کی ضرورت ہے۔ بلکہ بچے کو نماز میں اٹھانے اور رکھنے کے بارے میں حدیث صحیح اور صریح ہے اور اس میں شریعت کے قواعد کی مخالفت بھی نہیں مطابقت ہے۔‘‘"}],[1633,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کسی کو نماز میں اُونگھ آئے تو وہ سو جائے یہاں تک کہ نیند جاتی رہے۔ جب تم میں سے کوئی آدمی اُونگھنے کی حالت میں نماز پڑھے گا تو وہ نہیں جانتا ہو گا کہ وہ مغفرت طلب کرنا چاہے گا تو اپنی جان کو گالی دے دے گا۔‘‘","",{"k":"بخاری (212)، مسلم (786)، ترمذی (355)، نسائی (162)، ابوداؤد (1310)، ابن ماجه (1370)، احمد (25777)، مؤطا (259)، دارمی (1383).","e":"...... ۱۔ اس فرمان کا پس منظر حولاء بنت تویت والا واقعہ ہے کہ نبی اکرم صلی اللہ علیہ وسلم سیدہ عائشہ رضی اللہ عنہا کے پاس آئے تو ان کے پاس یہ حولاء بیٹھی تھیں، آپ صلی اللہ علیہ وسلم نے پوچھا یہ کون ہے تو سیدہ عائشہ رضی اللہ عنہا نے حولاء کی بہت تعریف کی کہ یہ بہت زیادہ نماز پڑھتی ہے، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا طاقت بھر عبادت کرو تم اکتا جاتے ہو۔ اللہ تعالیٰ نہیں اکتاتے، اللہ کی طرف سے سب سے زیادہ پسندیدہ دین کا وہ کام ہے جو ہمیشہ کیا جائے اور پھر آپ نے اس حدیث میں مذکورہ ہدایت بھی بیان فرمائی۔ (بخاری، کتاب الایمان، باب احب الدین الى الله ادومه: ۴۳)\n۲۔ معمولی نیند سے نماز خراب نہیں ہوتی۔ ایسی نیند جس سے انسان کو شعور نہ رہے اس سے وضو بھی ٹوٹ جاتا ہے اور نماز بھی خراب ہو جاتی ہے۔ ۳۔ اس سے یہ بھی ثابت ہوا کہ ہر کام میں احتیاط کو مدنظر رکھا جائے۔ ۴۔ عبادت کے لیے قلبی حضور اور خشوع و خضوع پیدا کیا جائے اور اطاعت کے کاموں کی بجا آوری میں مکروہات اور ناپسندیدہ کاموں سے اجتناب کیا جائے۔ اور یہ بھی ثابت ہوا کہ نماز میں دعا کرنا جائز ہے اگر نماز میں نیند غلبہ کر جائے تو پھر تھوڑا سا سستا کر پھر نماز پڑھیں تاکہ حواس برقرار ہو جائیں اور آدمی کو پتہ ہو کہ وہ کیا پڑھ رہا ہے۔"}],[1634,"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ انہوں نے عبداللہ بن حارث کو دیکھا کہ وہ نماز پڑھ رہا ہے اور اس کے سر کے بال پیچھے کو باندھے ہیں۔ پس ابن عباس رضی اللہ عنہ نے گرہ کو کھولنا شروع کر دیا۔ جب اس نے سلام پھیرا تو ابن عباس رضی اللہ عنہ کو کہا میرے بالوں سے تمہیں کیا غرض ہے؟ ابن عباس رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے، آپ نے فرمایا: ’’ایسا کرنے والوں کی مثال اس شخص جیسی ہے جس کے دونوں ہاتھ پس پشت باندھے ہوں۔‘‘ (مسلم)","",{"k":"مسلم (492)، نسائی (1114)، ابوداؤد (647)، احمد (2897)، دارمی (1381)."}],[1635,"سیدنا ابو سعید المقبری رضی اللہ عنہ سے روایت ہے کہ ابو رافع مولیٰ رسول اللہ صلی اللہ علیہ وسلم سیدنا حسن بن علی رضی اللہ عنہما کے پاس سے گذرا تو اس نے دیکھا کہ وہ نماز پڑھ رہے ہیں، اور اپنے بالوں کی چٹیا اپنی گردن میں باندھ دی ہے تو ابو رافع رضی اللہ عنہ نے وہ کھول دیں۔ پس حسن رضی اللہ عنہ نے غصے کے ساتھ دیکھا تو ابو رافع رضی اللہ عنہ نے کہا: اپنی نماز کی طرف متوجہ رہو اور غصہ نہ کرو میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے کہ یہ شیطان کا تالا ہے، یعنی شیطان کے بیٹھنے کی جگہ یعنی چٹیا باندھنے کے مقام پر۔","",{"k":"ابوداؤد (646)، حسن، البانی: 601، ترمذی (384)، احمد (26643)، دارمی (1380).","e":"...... سیدنا ابورافع رضی اللہ عنہ نے، سیدنا حسن بن علی رضی اللہ عنہما کو بال لٹکانے کا اس لیے حکم دیا تھا تاکہ یہ بھی سجدہ گاہ میں گریں اور ان کے ساتھ سجدہ کرنے میں شامل ہوں کیونکہ نبی اکرم صلی اللہ علیہ وسلم نے بالوں اور کپڑوں کو سمیٹنے سے منع کیا ہے۔ ۲۔ نماز میں کپڑا اور آستین چڑھانا اور بالوں کو پگڑی کے نیچے دوہرے کرنا یا کسی چیز کے ساتھ باندھ کر اوپر اکٹھا رکھنا سب منع ہے۔ اگر کوئی اس ممانعت کے خلاف کرتا ہے تو برا کرتا ہے مگر نماز درست ہوگی۔ (عون المعبود: ۱/۲۴۶)"}],[1636,"ہشام بن عروہ سے روایت ہے وہ اپنے باپ عروہ بن زبیر رضی اللہ عنہ سے بیان کرتے ہیں کہ عبداللہ بن ارقم رضی اللہ عنہ اپنے رفقاء کو نماز پڑھایا کرتے تھے۔ ایک دن نماز کا وقت آیا تو وہ رفع حاجت کے لیے چلے گئے، پھر واپس آئے تو کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے: ’’جب تم میں سے کسی کا رفع حاجت کا ارادہ ہو تو نماز سے پہلے حاجت رفع کرے۔‘‘","",{"k":"نسائی (852)، صحيح، البانی: 822، ترمذی (142)، ابوداؤد (88)، ابن ماجه (616)، احمد (15965)، مؤطا (381)، دارمی (1427)."}],[1637,"زید بن اسلم سے منقول ہے: سیدنا عمر رضی اللہ عنہ نے کہا تم میں سے کوئی شخص اس حال میں نماز نہ پڑھے کہ اپنے سرینوں کو خم کر رہا ہو۔","",{"k":"مؤطا."}],[1638,"ابن ابی عتیق سے روایت ہے اس نے کہا: میں نے اور قاسم رضی اللہ عنہ نے سیدہ عائشہ رضی اللہ عنہا کے پاس آپس میں بات چیت کی اور وہ بلند آواز سے باتیں کرنے والا تھا اور ام ولد کا بیٹا تھا۔ تو عائشہ رضی اللہ عنہا نے اس کو کہا: تو بھی اسی طرح باتیں کیوں نہیں کرتا جس طرح میرے بھائی کا یہ بیٹا بات کر رہا ہے اور میں جانتی ہوں کہ یہ چیز تیرے اندر کہاں سے آئی، اس کو اس کی ماں نے ادب سکھایا ہے اور تجھے تیری ماں نے سکھایا ہے۔ قاسم رضی اللہ عنہ کو اس بات پر غصہ آیا اور وہ عائشہ رضی اللہ عنہا سے ناراض ہوا۔ جب عائشہ رضی اللہ عنہا کا دستر خوان آتے دیکھا تو وہ اُٹھ کھڑا ہوا، عائشہ رضی اللہ عنہا نے کہا: تم کہاں چلے؟ اس نے کہا: میں نماز پڑھتا ہوں، کہا بیٹھئے، اس نے پھر کہا: میں نماز پڑھتا ہوں۔ اس نے کہا: اے دھوکا دینے والے بیٹھ جا۔ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے: ’’کھانا حاضر ہونے پر نماز نہیں جائز اور نہ اس شخص کی نماز جائز ہے جو بول و براز روک رہا ہو۔‘‘","",{"k":"مسلم (560)، ابوداؤد (89)، احمد (23928).","e":"...... ۱۔ ایک آدمی کھانا کھانا چاہتا ہے اور کھانا اس کے سامنے رکھ دیا گیا ہے، وہ پہلے کھانے سے فراغت حاصل کرے، نماز بعد میں پڑھ لے۔ ۲۔ اگر قضائے حاجت یا پیشاب کا زور ہو تو آدمی نماز نہ پڑھے، وجہ یہ ہے کہ کھانے کی شدید حاجت ہو اور قضائے حاجت کا زور ہو تو خشوع باقی نہیں رہتا۔ ان میں مصروفیت رہتی ہے اور بے چینی ہوتی ہے۔ علامہ عبید اللہ رحمانی رحمہ اللہ فرماتے ہیں: اگر کھانے یا حاجت روکنے کی صورت میں نماز پڑھی جائے تو کراہت ہے اگر کوئی پڑھ لیتا ہے تو نماز کفایت کر جائے گی۔ ایک اعتراض یہ ہو سکتا ہے کہ شرح السنۃ میں بغوی نے بیان کیا ہے کہ رسول اکرم صلی اللہ علیہ وسلم نے فرمایا کہ کھانے وغیرہ کی وجہ سے نماز مؤخر نہ کی جائے۔ (ابوداؤد، کتاب الاطعمہ) اس کا حل یہ ہے کہ (۱) یہ روایت ضعیف ہے، اس میں محمد بن میمون ابونضر کوفی زعفرانی ہے جو کہ منکر ہے۔ (۲) اگر کسی طرح اسے تسلیم بھی کر لیا جائے تو مطابقت یہ ہے کہ جب ان چیزوں یعنی کھانے اور حاجت کے آنے کی سخت شدت ہو تو پھر پہلے یہ کام کر لیے جائیں اور اگر اتنی زیادہ خواہش نہ ہو تو پھر نماز مؤخر نہ کی جائے۔ (مرعاۃ: ۲/۷۸)"}],[1639,"سیّدنا ابن عباس رضی اللہ عنہما مرفوع بیان کرتے ہیں: ’’جب تم میں سے کوئی شخص نماز میں کھڑا ہوا تو وہ اپنی آنکھیں بند نہ کرے۔‘‘ (طبرانی بروایت مدلس)","",{"k":"طبرانی کبیر: 10956، وفيه ليث بن ابي سليم وهو مدلس وقد عنعنه، هيثمي: 2450."}],[1640,"سیّدنا ابن عمرو بن العاص رضی اللہ عنہما نے مرفوع بیان کیا: ’’تم میں سے کوئی شخص اس حال میں نماز نہ پڑھے کہ اس کا کپڑا اس کی ناک پر ہو پس یہ شیطان کی لگام ہے۔‘‘ (الکبیر اور الاوسط بسند نرم)","",{"k":"طبرانی کبیر، اوسط وفيه ابن لهيعه وفيه كلام، هيثمي: 2451."}],[1641,"سیّدنا ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نماز میں اپنے چہرے سے پسینہ صاف کرتے تھے۔ (الکبیر بسند ضعیف)","",{"k":"طبرانی کبیر: 12/22، وفيه خارجة بن مصعب وهو ضعيف جدا، هيثمي: 2458."}],[1642,"حسن رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نماز میں داڑھی کو ہاتھ لگاتے تھے۔ (یہ حسن کی مرسل حدیث ہے)","",{"k":"ابو يعلى موصلي، وهو مرسل، هيثمي: 2466."}],[1643,"عدی بن ثابت اپنے باپ سے وہ اس کے دادا سے مرفوع بیان کرتے ہیں، فرمایا: ’’نماز میں چھینک، اُونگھ اور جمائی اور حیض، قے اور نکسیر شیطان سے ہیں۔‘‘ (ترمذی)","",{"k":"ترمذی (2748)، ضعیف، البانی: 522، ابن ماجه (969)."}],[1644,"سیّدنا ابن مسعود رضی اللہ عنہ نے کہا: جب نماز فرض ہو جائے تو اس کو ترک کر کے اس کے سوا کسی کام کے لیے مت جاؤ۔‘‘ (طبرانی)","",{"k":"طبرانی، ورجاله ثقات الا ان زياد الم يسمع من ابن مسعود، هيثمي: 2579."}],[1645,"سیّدہ عائشہ رضی اللہ عنہا سے حدیث مروی ہے: نبی کریم صلی اللہ علیہ وسلم گھر میں ہوتے اور بلال رضی اللہ عنہ اذان کہتے تو آپ صلی اللہ علیہ وسلم غسل کر کے نکلتے اور نماز پڑھتے تو میں آپ صلی اللہ علیہ وسلم کے رونے کی آواز سنتی تھی۔‘‘ (الموصلی کی طویل روایت)","",{"k":"موصلى ورجاله رجال الصحيح."}],[1646,"مطرف اپنے باپ سے روایت کرتے ہیں، اس نے کہا: میں نے نبی کریم صلی اللہ علیہ وسلم کو نماز پڑھتے دیکھا اور آپ صلی اللہ علیہ وسلم کے سینے میں رونے کی آواز یوں پیدا ہوتی جیسے چکی کی آواز ہوتی ہے۔ (ابوداؤد)","",{"k":"ابوداؤد (904)، صحيح، البانی: 799، نسائی (1214)، احمد (15891)."}],[1647,"اور نسائی کی روایت میں ہے: آپ صلی اللہ علیہ وسلم کے پیٹ سے ایسی آواز آتی جس طرح ہنڈیا کے اُبلنے کی آواز ہوتی ہے۔‘‘","",{"k":"نسائی (1214)، صحيح، البانی: 1156، ابوداؤد (904)، احمد (15877).","e":"...... ان احادیث میں دلیل ہے کہ رونے سے نماز باطل نہیں ہوتی، روتے ہوئے کچھ حرف بھی ظاہر ہو جائیں تو نماز میں فرق نہیں آتا بشرطیکہ رونا خشیت الٰہی سے آیا ہو۔ آہ! کھیل کود میں مصروف امت کے لوگ اس سے سبق حاصل کریں، اتنا مقدس سینہ اور اس قدر آہ وفغاں سے اللہ کی بارگاہ میں اہل رہا ہے، ہم ہیں کہ دنیا کی رونقوں میں کھوئے ہیں، سحر خیزی کی طرف اندوزیوں سے کتنے بے بہرہ ہیں۔"}],[1648,"سیّدنا ابو ہریرہ رضی اللہ عنہ مرفوع بیان کرتے ہیں: ’’جماعت کے ساتھ نماز پڑھنا تنہا نماز پڑھنے سے پچیس گنا زیادہ افضل ہے۔‘‘","",{"k":"ترمذی (216)، صحيح، البانی: 179، بخاری (477)، مسلم (649)، نسائی (838)، ابن ماجه (878)، احمد (10419)، مؤطا (291)، دارمی (1276)."}],[1649,"بخاری، مسلم اور نسائی نے زائد الفاظ کے ساتھ روایت کی ہے کہ رات کے فرشتے اور دن کے فرشتے فجر کی نماز میں جمع ہو جاتے ہیں، پھر ابو ہریرہ رضی اللہ عنہ کہتے تھے اگر بطور دلیل کے پڑھنا چاہو تو یہ آیت پڑھو: ’’اور قرآن پڑھ فجر کو، بے شک قرآن پڑھنا فجر کا حاضر کیا گیا ہے۔‘‘","",{"k":"بخاری (477)، مسلم (649)، نسائی (838)، ابن ماجه (878)، احمد (10419)، مؤطا (291)، دارمی (1276)."}],[1650,"ابو صالح کہتے ہیں میں نے ابو ہریرہ رضی اللہ عنہ سے سنا، وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایک آدمی کی جماعت کے ساتھ نماز اس کے گھر میں اور بازار میں پڑھی گئی نماز سے پچیس گنا بڑھ جاتی ہے۔ اور یہ اس لیے کہ جب وہ اچھی طرح وضو کرتا ہے اور پھر مسجد کی طرف نکل کر چلتا ہے اور اس کو گھر سے صرف نماز ہی نکالتی ہے، تو وہ جو قدم بھی رکھتا ہے تو اس کے ساتھ اس کا ایک درجہ بلند ہوتا ہے اور اس کی ایک خطا معاف ہوتی ہے۔ پھر جب وہ نماز پڑھتا ہے تو جب تک وہ نماز کی جگہ میں رہتا ہے فرشتے اس پر صلوات بھیجتے ہیں (کہتے ہیں) اے اللہ! اس پر صلوات نازل فرما، اس پر رحمت نازل کر۔ جو شخص تم میں سے نماز کے انتظار میں رہتا ہے وہ نماز میں ہی شمار کیا جاتا ہے۔‘‘","",{"k":"بخاری (647)، ابوداؤد (559)، احمد (10518)، مؤطا (385)."}],[1651,"اور ایک روایت میں ہے: ’’پس جب وہ مسجد میں داخل ہوتا ہے تو جب تک اس کو نماز رو کے رکھتی ہے وہ نماز ہی میں شمار کیا جاتا ہے۔‘‘","",{"k":"بخاری (659)، مسلم (649)، نسائی (838)، ابن ماجه (878)، احمد (10419)، مؤطا (291)، دارمی (1276)."}],[1652,"زائد روایت ہے: اے اللہ! اس کو بخش، اے اللہ! اس پر رجوع فرما اور توبہ قبول کر۔ جب تک وہ ایذا نہ پہنچائے اس میں یا وہ بے وضو نہ ہو۔‘‘","",{"k":"مسلم (649)، بخاری (4717)، ترمذی (216)، نسائی (838)، ابوداؤد (559)، ابن ماجه (787)، احمد (10364)، مؤطا (385)، دارمی (1276)."}],[1653,"موطا میں یہ مزید الفاظ ہیں: کہا: ’’اگر وہ نماز کی جگہ سے اُٹھا اور مسجد ہی میں دوسری جگہ بیٹھ گیا اور نماز کا انتظار کرتا رہا تو وہ نماز ہی میں شمار ہوتا ہے یہاں تک کہ نماز پڑھ لے۔‘‘","",{"k":"مؤطا (385)، بخاری (477)، نسائی (733)، ابوداؤد (559)، احمد (15018)."}],[1654,"سیّدنا ابو سعید خدری رضی اللہ عنہ مرفوع حدیث کرتے ہیں: ’’نماز با جماعت تنہا کی نماز سے پچیس درجے زیادہ فضیلت رکھتی ہے۔‘‘ (بخاری و ابوداؤد)","",{"k":"بخاری (646)، ابوداؤد (460)، ابن ماجه (788)، احمد (11129)."}],[1655,"اور یہ زیادہ کیا ہے: ’’اگر ویران علاقے میں نماز پڑھی اور رکوع و سجود اس کے مکمل کیے تو وہ پچاس درجات تک بڑھ جاتی ہے۔‘‘","",{"k":"ابوداؤد (560)، صحيح البانی: 524، بخاری (646)، ابن ماجه (788)، احمد (11129)."}],[1656,"سیّدنا ابن عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جماعت کے ساتھ ایک نماز اکیلے کی نماز سے ستائیس درجے افضل ہے۔‘‘","",{"k":"مسلم (650)، بخاری (645)، ترمذی (215)، نسائی (837)، ابن ماجه (789)، احمد (6419)، مؤطا (290)، دارمی (1277).","e":"...... ۱۔ ان احادیث سے ثابت ہوا کہ نماز ایک بہت ہی اعلیٰ عبادت ہے۔ ۲۔ نماز فجر اور نماز عصر کو دوسری نمازوں پر یہ عظمت حاصل ہے کہ ان میں فرشتوں کے دونوں گروہ جمع ہوتے ہیں، جبکہ دوسری نمازوں میں ایک گروہ حاضر ہوتا ہے، یہ ان نمازوں کے وقت کے شرف پر بھی دلالت ہے۔ علامہ عبید اللہ رحمانی رحمہ اللہ فرماتے ہیں کہ ان دونوں نمازوں کے وقت کے شرف کی وجہ یہ ہے کہ صبح کی نماز کے بعد رزق تقسیم ہوتا ہے اور دن کے آخر میں اعمال آسمان پر اٹھائے جاتے ہیں، ان دونوں نمازوں کا اہتمام کرنا اطاعت کا کام ہے۔ اس سے نمازی کے رزق و عمل میں برکت ہوتی ہے۔ (مرعاۃ: ۲/۶۵) ۳۔ جو فرشتے صبح اور عصر کے وقت اللہ کے سامنے جاتے ہیں وہ کراماً کاتبین کے علاوہ ہیں، کیونکہ یہ تو انسان سے ایک دو خاص مواقع کے علاوہ ہمہ وقت ساتھ رہتے ہیں۔ اور فرشتوں سے یہ پوچھنا کہ میرے بندوں کو کس حال میں چھوڑ کر آئے ہو یہ اس لیے ہے کہ اس کارخیر پر ان کی گواہی ثبت ہو جائے۔ ۴۔ نماز فجر کی ادائیگی کو فجر کا قرآن کہا گیا ہے جس میں فرشتے حاضر ہوتے ہیں، وجہ یہ ہے کہ اس میں طویل قراءت کی تلقین ہے اور ترغیب دلائی گئی ہے کہ قراءت کے لحاظ سے نماز فجر بہت طویل ہونی چاہیے۔\n۵۔ نماز دوسرے اعمال صالحہ پر بہت برتری رکھتی ہے کیونکہ فرشتے نمازی کے لیے مغفرت، توبہ اور رحمت کی دعا کرتے ہیں اور یہ بھی ثابت ہوا کہ مسجد میں بے وضو ہونے سے فرشتوں کی دعا، مغفرت اور استغفار سے محرومی ہو جاتی ہے حالانکہ فرشتوں کی دعا قبول ہوتی ہے۔ اگرچہ بے وضو مسجد میں بیٹھنا جائز ہے مگر باوضو ہو کر بیٹھنا زیادہ مفید ہے۔ ۶۔ نماز باجماعت کی ترغیب دی گئی ہے اور نماز باجماعت کے مختلف ثواب بیان ہوئے ہیں، چھبیس، ستائیس اور پچاس نمازوں کا اجر آیا ہے۔ ثواب کی تھوڑی مقدار زیادہ کی نفی نہیں کرتی، تعداد ثواب متعین کرنا مقصد نہیں۔ یا پھر پہلے رسول اکرم صلی اللہ علیہ وسلم نے کم مقدار ثواب کی بتائی پھر آپ کو زیادہ ثواب کی اطلاع ملی تو وہ بتا دی۔ (فتح الباری) باقی نماز باجماعت کو اتنی مقدار میں متعین کرنے کی حکمت کیا ہے، یہ عقل سے ماوراء ہے، یہ صرف اسرار نبوت کا معاملہ ہے، اس کے سامنے سرتسلیم خم کرنا ہے۔ زیادہ گہرائی میں جانے کی ضرورت نہیں۔"}],[1657,"ابو ہریرہ رضی اللہ عنہ اور ابن عباس رضی اللہ عنہما دونوں مرفوع بیان کرتے ہیں: ’’جس نے ان پانچ فرض نمازوں کی جماعت کے ساتھ حفاظت کی تو وہ ان لوگوں میں سے ہو گا جو جہنم کے پل سے چمکنے والی بجلی کی مانند گذر جائیں گے اور اس کو اللہ تعالیٰ ان لوگوں کے ساتھ اُٹھائے گا جو اوّل درجہ کی اطاعت کرنے والے ہوں گے اور اس کے لیے ہر رات اور دن ان کی حفاظت کے بدلے ہزار شہید کے اجر کے برابر ثواب ہوگا اور وہ شہید جو اللہ کی راہ میں قتل کیے گئے ہوں۔‘‘ (الاوسط بروایت مدلس)","",{"k":"طبرانی اوسط، وفيه بقية بن الوليد وهو مدلس وقد عنعنه، هيثمي: 2143."}],[1658,"سیدنا ابو درداء رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے فرماتے ہوئے سنا: جس شہر یا دیہات میں تین مرد ہوں اور ان کے درمیان نماز باجماعت قائم نہ ہو تو لا محالہ ان پر شیطان غالب آجاتا ہے پس تم نماز باجماعت اپنے اوپر لازم کر لو، یقیناً بھیڑیا دور رہنے والی بکری کو اُٹھاتا ہے۔ سائب نے کہا: مراد لفظ جماعت سے نماز کی جماعت ہے۔ رزین نے یہ زیادہ کلمات بھی ذکر کیے ہیں: اور تحقیق انسان کا بھیڑیا شیطان ہے جب انسان کو تنہا پاتا ہے تو اس کو کھا جاتا ہے۔‘‘","",{"k":"ابوداؤد (547)، حسن، البانی: 511، نسائی (857)، احمد (26968).","e":"...... ۱۔ جماعت کا تصور دو سے بھی پورا ہو جاتا ہے مگر تین آدمیوں کی قید لگا کر مکمل جماعت کا تصور دیا گیا ہے۔ ۲۔ جماعت لازم پکڑنے سے مراد ہے، نماز باجماعت پڑھیں، اگر یہ نماز باجماعت نہ پڑھے گا تو شیطان کا غلبہ ہوگا کیونکہ جماعت سے شیطان بھاگتا ہے، نماز باجماعت نہ پڑھنے سے شیطان کا غلبہ ہوتا ہے اور انسان ذکر الٰہی سے بے خبر ہو جاتا ہے تو شیطان اس پر تسلط جما لیتا ہے۔ جس طرح بکری کا چرواہا پاس نہ ہو اور وہ بکری ریوڑ سے کٹ جائے تو اسے بھیڑیا کھا جاتا ہے، یہی حالت اس کی ہے جو تنہا نماز پڑھنے کا عادی ہو جائے اسے بھی شیطان برباد کر دیتا ہے۔ ۳۔ اس حدیث سے یہی ثابت ہوتا ہے کہ نماز کی جماعت فرض ہے۔"}],[1659,"سیدنا ابو سعید رضی اللہ عنہ سے مروی ہے کہ ایک شخص آیا جبکہ رسول اللہ صلی اللہ علیہ وسلم نماز پڑھ چکے تھے، پس فرمایا: کون اس کے ساتھ کھڑا ہوتا ہے؟ پس ایک شخص اُٹھا اور اس نے آنے والے شخص کے ساتھ نماز پڑھی۔‘‘ (ترمذی، ابو داؤد)","",{"k":"ترمذی (220)، صحیح، البانی: 182، احمد (11399).","e":"...... ۱۔ مسند احمد: ۳/۸۵ میں ہے کہ اس پیچھے رہنے والے آدمی سے نبی اکرم صلی اللہ علیہ وسلم نے پوچھا کہ کس وجہ سے پیچھے رہے ہو؟ اس نے اپنا عذر پیش کیا تو وہ تنہا نماز پڑھنے لگا تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا کہ کوئی ہے جو اس پر مہربانی کرے اور اس کے جماعت کے اجر کو پورا کر دے تو سیدنا ابو بکر صدیق رضی اللہ عنہ نے اس کے ساتھ نماز پڑھی، جیسا کہ بیہقی: ۳/۷۰ میں وارد ہے۔ ۲۔ یہ حدیث دلیل ہے کہ اگر کوئی جماعت سے رہ گیا ہے تو وہ اکیلا ہو تو اس کے ساتھ جماعت کے لیے دوسرا مل جائے اگرچہ ملنے والا باجماعت نماز پڑھ چکا ہو۔ اس نظریہ کے خلاف جو دوسری جماعت کے ساتھ نہ پڑھنے کی دلیل ہے، اس پر تبصرہ کے بعد علامہ عبید اللہ فرماتے ہیں، جس کا مفہوم یہ ہے: ان میں سے راجح ترین بات یہی ہے کہ جو مسجد میں آتا ہے، وہاں مقرر امام نے جماعت کرا دی ہے اور اس آنے والے نے ابھی نماز نہیں پڑھی تو یہ دوسری جماعت کروا سکتا ہے۔ بشرطیکہ پہلی نماز سے کسی معقول عذر کی بنا پر پیچھے رہا ہو، بغیر عذر جماعت سے پیچھے رہنا گناہ ہے۔ (مرعاۃ: ۲/۱۳۲) آج کل یہ سستی عام ہے اور دوسری جماعت کے بل بوتے پر پہلی جماعت گزار دی جاتی ہے، یہ بھی خلاف شریعت ہے اور بوجہ عذر دوسری جماعت کی ممانعت یہ بھی خلاف شرع ہے، بوجہ عذر دوسری جماعت جائز ہے۔"}],[1660,"سیدنا عثمان رضی اللہ عنہ مرفوع بیان کرتے ہیں: ’’جس نے نماز عشاء جماعت کے ساتھ پڑھی تو گویا اس نے نصف رات قیام کیا اور جس نے نماز فجر جماعت کے ساتھ پڑھی تو گویا اس نے ساری رات نماز پڑھی۔‘‘","",{"k":"ترمذی (220)، صحیح البانی: 182، احمد (26968)."}],[1661,"سیدنا عثمان بن عفان رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جو شخص نماز عشاء میں حاضر ہوا اس کے لیے نصف رات کا قیام کرنے کے برابر اجر ہے اور جس نے نماز عشاء اور نماز فجر جماعت کے ساتھ پڑھیں تو اس کے لیے پوری رات قیام کرنے کا اجر ہے۔‘‘","",{"k":"ابو داؤد (555)، صحیح، البانی: 519، مسلم (656)، ترمذی (221)، احمد (493)، مؤطا (297)، دارمی (196).","e":"...... ۱۔ ہر ایک نماز کو نصف قیام کے قائم مقام قرار دیا گیا ہے، اگر صرف عشاء کی نماز باجماعت پڑھی تو نصف رات کے قیام کا اجر حاصل ہوگا اور فجر کی نماز باجماعت ہوگی تو نصف رات کے یہ قائم مقام ہوگی۔ لہذا دونوں نمازیں باجماعت ادا ہوں گی تو گویا ساری رات قیام کا اجر حاصل ہوگا۔ ۲۔ یاد رہے کہ اس میں ثواب کی مقدار بتائی گئی ہے، یہ نہیں کہ ایک آدمی رات قیام کرتا ہے یہ اس کے برابر ہو جاتا ہے کیونکہ اس طرح تو اس قیام کرنے والے سے انصاف نہ ہوگا کہ دونوں برابر ہوں، اس طرح تو اس کی محنت رائیگاں جائے گی ایسا نہیں بلکہ اس کا مقام اعلیٰ ہے مگر جو صبح اور عشاء کی نماز باجماعت پڑھے گا اس کے ثواب کی مقدار کا اندازہ یہ بتایا گیا ہے اور اس کے ثواب سے مشابہت دی گئی ہے کہ اسے رات کے قیام کرنے والے کی مانند اجر ملتا ہے عملاً وہ اس شب زندہ دار کی مانند نہیں۔"}],[1662,"سیدہ عائشہ رضی اللہ عنہا مرفوع بیان کرتی ہیں: ’’اگر لوگوں کو معلوم ہو کہ نماز عشاء میں بدھ کی رات حاضری کا فائدہ ہے تو وہ اس کے لیے ضرور آئیں خواہ ان کو سرین کے بل آنا پڑے۔‘‘","",{"k":"طبرانی اوسط، وفيه زكريا بن منظور وهو ضعيف، هيثمي: 2147."}],[1663,"سیدنا ابن عمر رضی اللہ عنہما مرفوع بیان کرتے ہیں: ’’جس نے نماز عشا جماعت کے ساتھ پڑھی اور مسجد سے خارج ہونے سے پہلے چار رکعات (سنت مؤکدہ) ادا کیں تو وہ لیلۃ القدر کے برابر ہیں۔‘‘ (یہ دو روایات الاوسط کی ہیں سند ضعیف)","",{"k":"طبرانی اوسط وفی اسناده ضعيف غير متهم بالكذب، هيثمي: 2148."}],[1664,"سیدنا ابی بن کعب رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک دن ہمیں نماز فجر پڑھائی اور جب سلام پھیرا تو فرمایا: کیا فلاں حاضر ہے؟ تو لوگوں نے کہا: نہیں ہے، پھر فرمایا: فلاں موجود ہے؟ تو لوگوں نے کہا: نہیں ہے۔ فرمایا: یہ دو نمازیں منافقین پر بہت ثقیل اور بھاری ہیں اور اگر وہ جان جائیں کہ ان میں کتنا اجر وثواب ہے تو وہ گھٹنوں کے بل چل کر بھی آئیں۔ اوّل صف فرشتوں کی صف جیسی ہے اور اگر تمہیں معلوم ہو کہ اس کی فضیلت کیا ہے اور ایک دوسرے سے آگے بڑھ کر آ جاؤ۔ ایک شخص کی نماز دوسرے شخص کے ساتھ مل کر پڑھنا، اس کی تنہا نماز پڑھنے سے زیادہ پاکیزہ ہے۔ اور اس کی نماز دو آدمیوں کے ساتھ، ایک آدمی کے ساتھ پڑھنے سے زیادہ عمدہ اور پاکیزہ ہے اور جتنے زیادہ ہوں گے اتنا اللہ کے نزدیک زیادہ پسند ہے۔‘‘ (ابو داؤد، نسائی)","",{"k":"ابوداؤد (554)، حسن، البانی: 518، نسائی (843)، احمد (20765)، دارمی (1269).","e":"...... ۱۔ ثابت ہوا کہ منافقوں پر نماز بوجھل ہوتی ہے لیکن نماز عشاء اور نماز فجر یہ تو بہت ہی زیادہ بھاری ہے۔ کیونکہ عشاء، آرام کا وقت ہے اور فجر کی نماز میں یہ نیند کی لذت لوٹ رہے ہوتے ہیں اور یہ دینی فریضہ تصور کر کے اور دلی طور پر تو نماز پڑھتے نہیں کہ ان مشکل اوقات میں یہ نمازوں میں آسانی سے حاضر ہوں۔ ان کا مقصد تو دکھلاوا ہوتا ہے جو ان اوقات میں پورا نہیں ہوتا، اس لیے ان دو نمازوں میں ان کا آنا بہت ہی زیادہ بوجھل ہے۔ ۲۔ لیکن اگر انہیں ان نمازوں میں حاضر ہونے کے اجر و ثواب کا علم ہو جائے تو یہ نہایت ہی تکلیف دہ حالات کے باوجود آئیں گے مگر ان کی قلبی کیفیت درست نہیں اس لیے انہیں اس قدر ثواب کے حصول کی تمنا نہیں ہوتی۔ مگر جب ایک مؤمن کامل کو اس ثواب کی قدر شناسی ہوتی ہے تو وہ تمام مشکلات راہ سر کرتے ہوئے ان نمازوں میں حاضر ہوتا ہے۔ ۳۔ اس سے یہ بھی ثابت ہوا کہ کم از کم ایک امام ہو، دوسرا مقتدی ہو تو یہ جماعت ہے، اس سے زیادہ جتنی جماعت بنتی جائے گی ان کے ثواب میں بھی اضافہ ہوگا اور اللہ تعالیٰ کے ہاں محبوب ہوتے جائیں گے۔ ۴۔ اس حدیث کے اس لفظ سے کہ آدمی کی دو آدمیوں کے ساتھ نماز ازکیٰ زیادہ بہتر ہے۔ نماز باجماعت کے فرض نہ ہونے پر استدلال کرتے ہیں یہ استدلال صحیح نہیں کیونکہ زیادہ پاکیزہ کہنے سے جماعت کی فرضیت کی نفی نہیں ہوتی۔"}],[1665,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے چالیس ایام جماعت کے ساتھ نماز اس طرح پڑھی کہ تکبیر تحریمہ (امام کے ساتھ) فوت نہ ہوئی تو اس کے لیے دو براءتیں اللہ تعالیٰ لکھ دیتا ہے آگ سے براءت اور نفاق سے براءت۔‘‘ (ترمذی)","",{"k":"ترمذی (241)، حسن، البانی: 200."}],[1666,"سیدنا عمر رضی اللہ عنہ مرفوع بیان کرتے ہیں: ’’جس نے مسجد میں جماعت سے چالیس ایام تک نماز پڑھی اور اول رکعت اس سے فوت نہ ہوئی تو اللہ تعالیٰ اس کو آگ سے آزادی لکھ دیتا ہے۔‘‘ (رزین)","",{"k":"رزین.","e":"...... ان احادیث میں امام کے ساتھ تکبیر تحریمہ میں ملنے کی فضیلت بیان ہوئی ہے کہ اس میں شامل ہونے سے آگ اور منافقت سے براءت حاصل ہوتی ہے یعنی اس چیز سے ایسا انسان بری ہو جاتا ہے کہ وہ منافقوں والا کوئی عمل کرے بلکہ اسے اخلاص کی دولت نصیب ہوتی ہے۔ اور آخرت میں بھی جو منافق کو عذاب ملے گا تکبیر تحریمہ میں شامل ہونے والا اس سے محفوظ رہے گا۔ اور اس کے لیے گواہی ہوگی کہ یہ منافق نہیں بلکہ مخلص مومن ہے۔ اسلاف سے جب تکبیر تحریمہ رہ جاتی تو وہ ایک دوسرے سے تین دن تک تعزیت کرتے تھے اور نماز باجماعت رہ جاتی تو سات دن تک تعزیت کرتے۔ (تحفۃ الاحوذی: ۱/۲۰۱)"}],[1667,"مجاہد نے کہا کہ ابن عباس رضی اللہ عنہما سے اس شخص کے بارے میں سوال کیا گیا جو دن کو روزہ رکھتا اور رات کو قیام کرتا ہے اور نہ جماعت میں حاضر ہوتا ہے اور نہ جمعہ میں، تو انہوں نے کہا: وہ آگ میں جائے گا۔‘‘ (ترمذی)","",{"k":"ترمذی (218)، ضعیف الاسناد، البانی: 36."}],[1668,"سیدنا ابو امامہ رضی اللہ عنہ مرفوع بیان کرتے ہیں: ’’جو گھر سے طہارت کر کے فرض نماز کے لیے نکلا اس کے لیے احرام باندھ کر حج کرنے والے کے برابر اجر ہے اور جو شخص مسجد کی طرف چاشت کے وقت دو رکعات ادا کرنے کے لیے نکلا، اس کو اس کے سوا دوسری کوئی غرض نہیں لائی اس کا اجر عمرہ کرنے والے کے برابر ہے۔ اور ایک نماز کے بعد دوسری نماز جن دو کے درمیان لغو بات نہ ہو وہ اعلیٰ علیین میں لکھی جاتی ہیں۔‘‘ (ابو داؤد)","",{"e":"...... ۱۔ باوضو گھر سے مسجد کی جانب روانہ ہونے والے نمازی کو حاجی کی مانند اجر والا کہا گیا ہے، حج تو وہی ہوتا ہے جو عرفات میں ادا کیا جائے، یہاں صرف نمازی کے ہر قدم کو حج کے ثواب کی مقدار کے مطابق قرار دیا گیا ہے۔ اور احرام والے حاجی کی صفت اس لیے بیان کی گئی ہے کہ اس میں ثواب مکمل طور پر حاصل ہوتا ہے، اسی طرح اس مسجد کی طرف جانے والے باوضو نمازی کا اجر بھی مکمل ہوتا ہے۔ ۲۔ اس میں نماز چاشت کے لیے دنیاوی مصروفیات چھوڑ کر جانے کی فضیلت بھی بیان ہوئی ہے کہ اسے عمرہ کی مقدار کے مطابق اجر ملتا ہے۔ ۳۔ اس میں مسلسل نمازوں کے خیال رکھنے کا درجہ بھی بیان ہوا ہے کہ اس کا رتبہ اعلی علیین تک پہنچ جاتا ہے، یہ وہ مقام ہے جو ساتویں آسمان پر ہے، یہاں صالح لوگوں کے اعمال بلند ہوتے ہیں۔ (عون المعبود: ۱/۲۱۹)"}],[1669,"سیدنا ابی بن کعب رضی اللہ عنہ سے مروی ہے کہ ایک شخص تھا انصار میں سے، مجھے اس سے زیادہ مسجد سے دور رہنے والا کوئی شخص معلوم نہیں ہے، اور اس کی کوئی نماز جماعت سے مؤخر نہ ہوتی تھی۔ اس کو کہا گیا یا خود میں نے اس کو کہا: اگر تو ایک گدھا خریدتا اور اس پر تاریکی میں اور پھر دھوپ کے وقت سوار ہوا کرتا۔ اس نے کہا: مجھے یہ پسند نہیں ہے کہ میرا گھر مسجد کے پہلو میں ہو، میرا ارادہ ہے کہ میرا مسجد کی طرف چل کر آنا اور میرا لوٹنا جب میں اپنے عیال کی طرف لوٹتا ہوں سب لکھا جائے۔ پس نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ نے یہ سب اجر و ثواب تیرے لیے جمع کر دیا ہے۔‘‘","",{"k":"مسلم (663)، ابوداؤد (557)، ابن ماجہ (783)، احمد (20709)، دارمی (1284)."}],[1670,"اور ایک روایت میں ہے: اللہ نے تجھے دے دیا، اللہ نے تجھے پورا پورا دے دیا جو تو نے شمار کیا ہے۔ (مسلم اور ابو داؤد)","",{"k":"ابوداؤد (557)، صحیح: 521، ابن ماجہ (783)، احمد (20709)، دارمی (1284)."}],[1671,"سیدنا ابو ہریرہ رضی اللہ عنہ مرفوع روایت کرتے ہیں: ’’جو دور ہو اور جو اس سے بھی مسجد سے دور ہو اس کا اجر بڑا ہے۔‘‘","",{"k":"ابوداؤد (556)، ابن ماجہ (782)، صحیح: 520."}],[1672,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ مسجد کے ارد گرد کچھ پلاٹ خالی تھے، تو بنو سلمہ نے ارادہ کیا کہ وہ منتقل ہو کر مسجد کے قریب چلے آئیں۔ پس ان کو نبی کریم صلی اللہ علیہ وسلم ملے تو انہوں نے فرمایا: مجھے خبر پہنچی ہے کہ تم مسجد کے قریب منتقل ہونا چاہتے ہو۔ انہوں نے کہا: اے اللہ کے رسول! ہاں یہ بات اسی طرح ہے۔ فرمایا: بنو سلمہ اپنے گھر نہ چھوڑو تمہارے نشانات قدم لکھے جاتے ہیں، تم اپنے گھر لازم پکڑو! تمہارے نشانِ قدم لکھے جاتے ہیں۔ تو انہوں نے کہا: ’’پھر تو ہمیں منتقل ہونے میں کوئی مسرت اور دلچسپی نہیں ہے۔‘‘ (مسلم)","",{"k":"مسلم (665)، احمد (14772)."}],[1673,"بخاری کی روایت جو انس رضی اللہ عنہ سے منقول ہے اس کی مثل ہے اور اس میں یہ بھی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کو مدینے کا خالی ہونا ناپسند تھا۔","",{"k":"بخاری (1887)، ابن ماجہ (784)، احمد (13359).","e":"...... ۱۔ اس سے ثابت ہوتا ہے کہ صحابہ کرام رضی اللہ عنہم ثواب کے کاموں میں بہت زیادہ برق رفتار تھے اور یہ بھی ثابت ہوا کہ مسجد میں آنے جانے کے لیے جو قدم چلتے ہیں ان کے لیے ثواب حاصل ہوتا ہے اور یقینی اجر ملتا ہے، بشرطیکہ رضائے الٰہی مقصد خاطر ہو۔ ۲۔ ان میں اس آیہ مبارکہ کی وضاحت سے ﴿وَنَكْتُبُ مَا قَدَّمُوا وَآثَارَهُمْ﴾ (یس: ۱۲) جو انہوں نے آگے بھیجا اور ان کے نشانات ہیں ہم انہیں لکھتے ہیں۔ مقصد ہے کہ بنو سلمہ سے آپ صلی اللہ علیہ وسلم نے کہا تھا جب تم مسجد کی جانب زیادہ قدم اٹھا کر آؤ گے تو تمہارے نشانات قدم لکھے جائیں گے، لہذا انہی گھروں میں رہو۔ ۳۔ ان احادیث سے ثابت ہوا کہ اعمال خیر میں جب خلوص کی آمیزش ہو تو ان کے آثار نیکیاں بن جاتی ہیں۔ یہ بھی ثابت ہوا کہ مسجد کے قریب ہی رہائش رکھنا مستحب ہے مگر جب دور رہنے میں زیادہ نفع ہو تو پھر دور رہنے میں گنجائش ہے۔ جس طرح اس حدیث میں مسجد کی جانب زیادہ قدم چلنے کا زیادہ ثواب بتایا گیا ہے، نبی اکرم صلی اللہ علیہ وسلم نے بنو سلمہ کو مسجد کے قریب آنے سے منع نہ کیا تھا بلکہ وجہ بتائی تھی کہ قریب آنے میں اچھائی ہے مگر مدینہ کے کنارے اس طرح تو خالی پڑ جائیں گے، اس لیے آپ صلی اللہ علیہ وسلم نے مسجد کے قریب رہائش کی فضیلت کے عوض دور سے مسجد میں آنے جانے کا ثواب بتا دیا کیونکہ مسجد میں دور سے آنے میں مشقت ہوتی ہے اس لیے اس کا اجر بڑھ جاتا ہے۔"}],[1674,"سیدنا ابن مسعود رضی اللہ عنہ سے روایت ہے کہ جو یہ پسند کرتا ہے کہ وہ اللہ تعالیٰ سے بحیثیت مسلمان ملاقات کرے تو وہ پانچ نمازوں کی حفاظت کرے جہاں بھی ان کی اذان ہو، اللہ تعالیٰ نے تمہارے نبی صلی اللہ علیہ وسلم پر ہدایت کے طریقے مشروع و مقرر کر دیے ہیں، اور اگر تم اپنے گھروں میں نماز پڑھنے لگو جیسے وہ پیچھے رہنے والا اپنے گھر میں پڑھتا ہے تو تم اپنے نبی صلی اللہ علیہ وسلم کی سنت ترک کر دو گے اور اگر سنت ترک کرو گے تو گمراہ ہو جاؤ گے۔ جو شخص اچھی طرح وضو کر کے پھر کسی مسجد کی طرف ان مساجد میں سے چلتا ہے تو اللہ تعالیٰ ہر قدم پر اس کی ایک نیکی لکھتا ہے اور ایک درجہ بلند کرتا ہے اور ایک گناہ بھی معاف کر دیتا ہے۔ ہم نے اپنا یہ حال بھی دیکھا کہ خالص منافق کے علاوہ کوئی شخص نماز سے پیچھے نہیں رہتا تھا۔ ایسا بھی ہوتا کہ کوئی آدمی دو آدمیوں کے درمیان سہارا دے کر لایا جاتا یہاں تک کہ صف میں لا کھڑا کیا جاتا تھا۔","",{"k":"مسلم (654)، ابوداؤد (550)، ابن ماجہ (777)، احمد (3554)، دارمی (1277).","e":"...... صحابہ کرام رضی اللہ عنہم اس شخص پر منافقت کا گمان کرتے تھے جو بلا عذر نماز باجماعت سے پیچھے رہتا تھا اور یہ نافرمانی کے لحاظ سے منافق ہوتا تھا کیونکہ یہی نفاق اس کے نماز سے پیچھے رہنے کا باعث تھا یا پھر معذور پیچھے رہتا تھا۔ اس سے ثابت ہوتا ہے کہ نماز باجماعت فرض ہے، اسی لیے صحابہ کرام رضی اللہ عنہم سہارا لے کر بھی مسجد کی جماعت میں حاضر ہوتے تھے۔ اور ہم اگر بلا وجہ نماز باجماعت ادا نہ کریں گے تو گمراہ ہو جائیں گے۔ اور اس میں مسجد میں جانے کی فضیلت بھی بیان ہوئی ہے کہ ہر قدم نیکی اور بلندی ہے اور گناہوں کے مٹانے کا باعث ہے۔ اللہ اکبر! ہم آج نماز باجماعت مسجد میں ادا کرنے میں سستی کا مظاہرہ کرتے ہیں اور کتنی ہی زیادہ رفعتوں سے محروم رہتے ہیں۔"}]])